"""# **6.18. Extraer métricas ROM**"""

def extract_rom_metrics(
    kin_test_list
):

    segment_columns = {

        "Tronco":
            "trunk_smooth",

        "Cuello":
            "neck_smooth",

        "Pierna izquierda":
            "legs_left_smooth",

        "Pierna derecha":
            "legs_right_smooth",

        "Brazo izquierdo":
            "arms_left_smooth",

        "Brazo derecho":
            "arms_right_smooth",

        "Antebrazo izquierdo":
            "forearms_left_smooth",

        "Antebrazo derecho":
            "forearms_right_smooth",

        "Muñeca izquierda":
            "wrists_left_smooth",

        "Muñeca derecha":
            "wrists_right_smooth"
    }

    rows = []

    for test in kin_test_list:

        df = test["df"]

        for segment, column in segment_columns.items():

            signal = df[column].dropna()

            if len(signal) < 5:
                continue

            rom = (
                signal.max()
                -
                signal.min()
            )

            rows.append({

                "subject":
                    test["subject"],

                "id":
                    test["id"],

                "test_type":
                    test["test_type"],

                "phase":
                    test["phase"],

                "segment":
                    segment,

                "ROM":
                    rom
            })

    return pd.DataFrame(rows)

"""# **6.19. Cálcular fase ROM**"""

def compute_phase_rom(
    kin_test_list,
    subject,
    test_type
):

    segment_map = {

        "Tronco":
            "trunk_smooth",

        "Cuello":
            "neck_smooth",

        "Pierna izquierda":
            "legs_left_smooth",

        "Pierna derecha":
            "legs_right_smooth",

        "Brazo izquierdo":
            "arms_left_smooth",

        "Brazo derecho":
            "arms_right_smooth",

        "Antebrazo izquierdo":
            "forearms_left_smooth",

        "Antebrazo derecho":
            "forearms_right_smooth",

        "Muñeca izquierda":
            "wrists_left_smooth",

        "Muñeca derecha":
            "wrists_right_smooth"
    }

    rows = []

    for segment, column in segment_map.items():

        for evaluation_phase in ["A", "D"]:

            tests = [

                t for t in kin_test_list

                if (
                    t["subject"] == str(subject).zfill(2)
                    and
                    t["test_type"] == test_type
                    and
                    t["phase"] == evaluation_phase
                )
            ]

            for movement_phase in [1, 2, 3, 4]:

                rom_values = []

                for test in tests:

                    df_phase = test["df"][
                        test["df"]["phase"]
                        ==
                        movement_phase
                    ]

                    if len(df_phase) < 5:
                        continue

                    signal = df_phase[
                        column
                    ].values

                    rom = (
                        np.max(signal)
                        -
                        np.min(signal)
                    )

                    rom_values.append(
                        rom
                    )

                rows.append({

                    "segment":
                        segment,

                    "evaluation":
                        "Antes"
                        if evaluation_phase == "A"
                        else "Después",

                    "phase":
                        f"F{movement_phase}",

                    "ROM":
                        np.mean(rom_values)
                        if len(rom_values) > 0
                        else np.nan
                })

    return pd.DataFrame(rows)

