"""# **6.22. Cálcular fase ROM por condición**"""

def compute_phase_rom_by_condition(
    kin_test_list,
    subject,
    evaluation_phase
):

    segment_map = {

        "Tronco": "trunk_smooth",
        "Cuello": "neck_smooth",

        "Pierna izquierda": "legs_left_smooth",
        "Pierna derecha": "legs_right_smooth",

        "Brazo izquierdo": "arms_left_smooth",
        "Brazo derecho": "arms_right_smooth",

        "Antebrazo izquierdo": "forearms_left_smooth",
        "Antebrazo derecho": "forearms_right_smooth",

        "Muñeca izquierda": "wrists_left_smooth",
        "Muñeca derecha": "wrists_right_smooth"
    }

    rows = []

    for segment, column in segment_map.items():

        for test_type in ["PB", "PE"]:

            tests = [

                t for t in kin_test_list

                if (
                    t["subject"] == str(subject).zfill(2)
                    and
                    t["test_type"] == test_type
                    and
                    t["phase"] == evaluation_phase
                )
            ]

            for movement_phase in [1,2,3,4]:

                rom_values = []

                for test in tests:

                    df_phase = test["df"][
                        test["df"]["phase"]
                        ==
                        movement_phase
                    ]

                    if len(df_phase) < 5:
                        continue

                    signal = df_phase[
                        column
                    ].values

                    rom = (
                        np.max(signal)
                        -
                        np.min(signal)
                    )

                    rom_values.append(rom)

                if len(rom_values) == 0:
                    continue

                rows.append({

                    "segment": segment,

                    "condition": test_type,

                    "phase": f"F{movement_phase}",

                    "mean": np.mean(
                        rom_values
                    ),

                    "std": np.std(
                        rom_values,
                        ddof=1
                    ) if len(rom_values) > 1 else 0,

                    "n": len(
                        rom_values
                    )
                })

    return pd.DataFrame(rows)

"""# **6.23. Graficar PB-PE petroleum style**"""

def plot_pb_pe_petroleum_style(
    rom_df,
    subject,
    evaluation_phase,
    save_path=None
):

    PB_COLOR = "#5B2A86"      # violeta petróleo
    PE_COLOR = "#0F8B8D"      # verde petróleo

    CONNECTOR = "#E5E5E5"
    GRID = "#EFEFEF"

    POSITIVE = "#0F8B8D"
    NEGATIVE = "#C44536"

    plt.rcParams.update({

        "font.family": "serif",

        "axes.facecolor": "white",
        "figure.facecolor": "white",

        "axes.spines.top": False,
        "axes.spines.right": False,

        "axes.edgecolor": "#D5D5D5",

        "xtick.color": "#555555",
        "ytick.color": "#555555"
    })

    segment_order = [

        "Tronco",
        "Cuello",

        "Pierna izquierda",
        "Pierna derecha",

        "Brazo izquierdo",
        "Brazo derecho",

        "Antebrazo izquierdo",
        "Antebrazo derecho",

        "Muñeca izquierda",
        "Muñeca derecha"
    ]

    phases = [
        "F1",
        "F2",
        "F3",
        "F4"
    ]

    all_deltas = []
    for segment in segment_order:

      tmp = rom_df[
          rom_df["segment"] == segment
      ]

      for phase in phases:

        pb = tmp[
            (tmp["condition"]=="PB")
            &
            (tmp["phase"]==phase)
        ]

        pe = tmp[
            (tmp["condition"]=="PE")
            &
            (tmp["phase"]==phase)
        ]

        if len(pb) and len(pe):

          all_deltas.append(

                abs(
                    pe["mean"].iloc[0]
                    -
                    pb["mean"].iloc[0]
                    )
                )

    max_delta = max(all_deltas)

    fig, axs = plt.subplots(
        5,
        2,
        figsize=(16, 18)
    )

    axs = axs.flatten()

    for ax, segment in zip(
        axs,
        segment_order
    ):

        data = rom_df[
            rom_df["segment"] == segment
        ]

        y_positions = np.arange(
            len(phases)
        )

        for stripe in range(len(phases)):
          ax.axhspan(

              stripe - 0.5,
              stripe + 0.5,
              color="#FAFAFA"
              if stripe % 2 == 0
              else "#FFFFFF",
              zorder=0
          )

        for i, phase in enumerate(phases):

            pb = data[
                (data["condition"] == "PB")
                &
                (data["phase"] == phase)
            ]

            pe = data[
                (data["condition"] == "PE")
                &
                (data["phase"] == phase)
            ]

            if len(pb) == 0 or len(pe) == 0:
                continue

            pb_mean = pb["mean"].iloc[0]
            pb_sd   = pb["std"].iloc[0]
            pe_mean = pe["mean"].iloc[0]
            pe_sd   = pe["std"].iloc[0]
            delta = pe_mean - pb_mean

            line_width = np.interp(
                abs(delta),
                [0, max_delta],
                [3, 7]
            )

            ax.hlines(
                y=i,
                xmin=min(pb_mean, pe_mean),
                xmax=max(pb_mean, pe_mean),
                color=CONNECTOR,
                linewidth=line_width,
                zorder=1
            )

            ax.fill_betweenx(

                [i - 0.12, i + 0.12],

                pb_mean - pb_sd,

                pb_mean + pb_sd,

                color=PB_COLOR,

                alpha=0.18,

                linewidth=0,

                zorder=2
            )

            ax.fill_betweenx(

                [i - 0.12, i + 0.12],

                pe_mean - pe_sd,

                pe_mean + pe_sd,

                color=PE_COLOR,

                alpha=0.18,

                linewidth=0,

                zorder=2
            )

            ax.scatter(

                pb_mean,

                i,

                s=130,

                color=PB_COLOR,

                edgecolor="white",

                linewidth=1.8,

                zorder=5
            )

            ax.scatter(

                pe_mean,

                i,

                s=130,

                color=PE_COLOR,

                edgecolor="white",

                linewidth=1.8,

                zorder=5
            )

            if abs(delta) > 5:

              ax.text(
                  pb_mean,
                  i - 0.35,
                  f"{pb_mean:.1f}",
                  ha="center",
                  fontsize=7,
                  color=PB_COLOR
               )

              ax.text(
                  pe_mean,
                  i - 0.35,
                  f"{pe_mean:.1f}",
                  ha="center",
                  fontsize=7,
                  color=PE_COLOR
              )

            x_mid = (
                pb_mean + pe_mean
            ) / 2

            delta_color = (
                POSITIVE
                if delta > 0
                else NEGATIVE
            )

            ax.annotate(

                f"Δ {delta:+.1f}°",

                xy=(x_mid, i),

                xytext=(0, 10),

                textcoords="offset points",

                ha="center",

                fontsize=8,

                fontweight="bold",

                color=delta_color
            )


        ax.set_title(

            segment,

            fontsize=12,

            fontweight="semibold",

            color="#2F2F2F",

            pad=10
        )

        ax.set_yticks(
            y_positions
        )

        ax.set_yticklabels(
            phases,
            fontsize=9
        )

        ax.grid(

            axis="x",

            color=GRID,

            linewidth=0.8
        )

        ax.set_xlabel(
            "ROM (°)",
            fontsize=9
        )

        ax.tick_params(
            labelsize=8
        )

        ax.margins(x=0.05)

    fig.suptitle(
        f"Comparación PB vs PE · "
        f"Sujeto {str(subject).zfill(2)} · "
        f"{evaluation_phase}",
        fontsize=12,
        fontweight="semibold",
        color="#22313F",
        y=0.975
    )

    fig.text(
        0.5,
        0.95,
        "Punto: media · Banda: media ± 1 DE",
        ha="center",
        fontsize=10,
        color="#707070"
    )

    legend_elements = [

        Line2D(

            [0],
            [0],

            marker="o",

            color=PB_COLOR,

            markersize=8,

            linewidth=2,

            label="PB (Básico)"
        ),

        Patch(
            facecolor=PB_COLOR,
            alpha=0.18,
            edgecolor="none",
            label="PB ±1 SD"
        ),

        Line2D(

            [0],
            [0],

            marker="o",

            color=PE_COLOR,

            markersize=8,

            linewidth=2,

            label="PE (Extremo)"
        ),

        Patch(
            facecolor=PE_COLOR,
            alpha=0.18,
            edgecolor="none",
            label="PE ±1 SD"
        )

    ]

    fig.legend(

        handles=legend_elements,

        loc="upper center",

        bbox_to_anchor=(0.5, 0.945),

        ncol=4,

        frameon=False,

        fontsize=11
    )

    plt.subplots_adjust(

        top=0.90,

        bottom=0.05,

        left=0.08,

        right=0.98,

        hspace=0.42,

        wspace=0.18
    )

    if save_path is not None:
      os.makedirs(
          save_path,
          exist_ok=True
    )

      filename = os.path.join(
          save_path,
          f"{int(subject):02d}_"
          f"{evaluation_phase}_"
          f"PB_PE_ROM.png"
      )

      plt.savefig(
          filename,
          dpi=600,
          bbox_inches="tight",
          facecolor="white",
          edgecolor="none",
          format="png"

      )

      print(f"✔ Guardado: {filename}")
      plt.close(fig)

    else:
      plt.show()

