"""# **6.26. Score trunk**"""

def score_trunk(
    trunk_angle,
    test_type,
    movement_phase
):
    """
    Puntuación REBA del tronco.
    """

    if trunk_angle <= 20:

        score = 2

    elif trunk_angle <= 60:

        score = 3

    else:

        score = 4

    if (
        test_type == "PE"
        and movement_phase in [2, 3]
    ):
        score += 1

    return min(score, 5)


def score_neck(
    neck_angle,
    test_type,
    movement_phase
):
    """
    Puntuación REBA del cuello.
    """

    if neck_angle <= 20:

        score = 1

    else:

        score = 2

    if (
        test_type == "PE"
        and movement_phase in [2, 3]
    ):
        score += 1

    return min(score, 3)

def score_legs(
    left_leg_angle,
    right_leg_angle
):
    """
    Puntuación REBA piernas.
    Se toma la mayor puntuación entre ambas piernas.
    """

    def leg_side_score(angle):

        score = 1

        if 30 <= angle <= 60:

            score += 1

        elif angle > 60:

            score += 2

        return score

    left_score = leg_side_score(
        left_leg_angle
    )

    right_score = leg_side_score(
        right_leg_angle
    )

    return max(
        left_score,
        right_score
    )

def score_arm(
    left_arm_angle,
    right_arm_angle,
    movement_phase
):
    """
    Puntuación REBA brazo.
    Se toma el mayor score entre ambos brazos.
    """

    def arm_side_score(angle):

        if angle <= 20:

            score = 1

        elif angle <= 45:

            score = 2

        elif angle <= 90:

            score = 3

        else:

            score = 4

        if movement_phase in [2, 3]:

            score += 1

        return score

    left_score = arm_side_score(
        left_arm_angle
    )

    right_score = arm_side_score(
        right_arm_angle
    )

    return max(
        left_score,
        right_score
    )

def score_forearm(
    left_forearm_angle,
    right_forearm_angle
):
    """
    Puntuación REBA antebrazo.
    Se toma el mayor score entre ambos antebrazos.
    """

    def forearm_side_score(angle):

        if 60 <= angle <= 100:

            return 1

        return 2

    left_score = forearm_side_score(
        left_forearm_angle
    )

    right_score = forearm_side_score(
        right_forearm_angle
    )

    return max(
        left_score,
        right_score
    )

def score_wrist(
    left_wrist_angle,
    right_wrist_angle
):
    """
    Puntuación REBA muñeca.
    Se toma el mayor score entre ambas muñecas.
    """

    def wrist_side_score(angle):

        if angle <= 15:

            score = 1

        else:

            score = 2

        score += 1

        return min(score, 3)

    left_score = wrist_side_score(
        left_wrist_angle
    )

    right_score = wrist_side_score(
        right_wrist_angle
    )

    return max(
        left_score,
        right_score
    )

