"""# **6.33. Compute Average REBA Profile**"""

def compute_average_reba_profile(
    tests,
    n_points=101
):
    """
    Calcula el perfil promedio de REBA.

    Parámetros
    ----------
    tests : list
        Lista de pruebas.
    n_points : int
        Número de puntos normalizados.

    Retorna
    -------
    dict
    """

    signals = []

    for test in tests:

        df = test["df"]

        if "reba_score" not in df.columns:

            raise ValueError(
                "No existe la columna reba_score"
            )

        signal = df["reba_score"].values

        signal_norm = normalize_signal(
            signal,
            n_points=n_points
        )

        signals.append(
            signal_norm
        )

    signals = np.asarray(
        signals
    )

    mean_profile = np.mean(
        signals,
        axis=0
    )

    std_profile = np.std(
        signals,
        axis=0,
        ddof=1
    )

    return {
        "mean": mean_profile,
        "std": std_profile,
        "all_signals": signals,
        "n": len(signals),
        "x": np.linspace(
            0,
            100,
            n_points
        )
    }

for test in kin_test_list:

    test["df"] = compute_reba_dataframe(
        test["df"],
        test["test_type"]
    )

"""# **6.34. Classify Risk Level**"""

def classify_risk_level(
    score
):
    """
    Clasificación de riesgo según tu escala.
    """

    if score == 1:
        return "Inapreciable"

    elif score <= 3:
        return "Bajo"

    elif score <= 7:
        return "Medio"

    elif score <= 10:
        return "Alto"

    return "Muy Alto"

"""# **6.35. Compute Phase REBA Statistics**"""

def compute_phase_reba_statistics(
    tests
):
    """
    Calcula estadísticas REBA por fase.

    Retorna
    -------
    dict
    """

    phase_stats = {}

    for phase in [1, 2, 3, 4]:

        phase_scores = []

        for test in tests:

            df = test["df"]

            phase_scores.extend(
                df.loc[
                    df["phase"] == phase,
                    "reba_score"
                ].values
            )

        phase_scores = np.asarray(
            phase_scores
        )

        mean_score = np.mean(
            phase_scores
        )

        std_score = np.std(
            phase_scores,
            ddof=1
        )

        dominant_risk = classify_risk_level(
            round(mean_score)
        )

        phase_stats[phase] = {
            "mean": mean_score,
            "std": std_score,
            "risk": dominant_risk,
            "n": len(phase_scores)
        }

    all_scores = []

    for test in tests:

        all_scores.extend(
            test["df"]["reba_score"]
        )

    all_scores = np.asarray(
        all_scores
    )

    phase_stats["global"] = {
        "mean": np.mean(all_scores),
        "std": np.std(
            all_scores,
            ddof=1
        ),
        "risk": classify_risk_level(
            round(
                np.mean(all_scores)
            )
        ),
        "n": len(all_scores)
    }

    return phase_stats

