"""# **6.36. Add Phase Separators**"""

def add_phase_separators(
    ax,
    phase_limits
):
    """
    Añade separadores verticales y etiquetas
    de las fases del movimiento.
    """

    boundaries = [
        phase_limits[1],
        phase_limits[2],
        phase_limits[3]
    ]

    for boundary in boundaries:

        ax.axvline(
            boundary,
            color="#6B7280",
            linestyle=":",
            linewidth=1.2,
            alpha=0.75,
            zorder=1
        )

    centers = [
        phase_limits[1] / 2,
        (phase_limits[1] + phase_limits[2]) / 2,
        (phase_limits[2] + phase_limits[3]) / 2,
        (phase_limits[3] + 100) / 2
    ]

    labels = [
        "F1\nElevación",
        "F2\nPrimer ciclo",
        "F3\nSegund ciclo",
        "F4\nDescenso"
    ]

    y_top = ax.get_ylim()[1]

    for center, label in zip(
        centers,
        labels
    ):

        ax.text(
            center,
            y_top,
            label,
            ha="center",
            va="center",
            fontsize=10,
            fontweight="semibold",
            color="#6B7280",
            zorder=5
        )

"""# **6.37. Plot REBA Publication Figure**"""

def plot_reba_publication_figure(
    kin_test_list,
    subject,
    test_type,
    phase,
    save=False,
    output_dir=None
):

    tests = [

        test

        for test in kin_test_list

        if (
            test["subject"] == str(subject).zfill(2)
            and
            test["test_type"] == test_type
            and
            test["phase"] == phase
        )
    ]

    if len(tests) == 0:

        raise ValueError(
            "No se encontraron pruebas."
        )

    profile = compute_average_reba_profile(
        tests
    )

    phase_limits = (
        compute_average_phase_boundaries(
            tests
        )
    )

    phase_stats = (
        compute_phase_reba_statistics(
            tests
        )
    )

    n = len(tests)

    mean_smooth = savgol_filter(
        profile["mean"],
        window_length=9,
        polyorder=2

    )

    ci95 = (
        1.96
        * profile["std"]
        / np.sqrt(n)

    )

    ci95_smooth = savgol_filter(
        ci95,
        window_length=9,
        polyorder=2
    )

    upper = mean_smooth + ci95_smooth
    lower = mean_smooth - ci95_smooth

    fig = plt.figure(
        figsize=(17, 10)
    )

    gs = fig.add_gridspec(
        2,
        1,
        height_ratios=[8.6,1.4],
        hspace=0.2
    )

    ax = fig.add_subplot(gs[0])

