    for (row, col), cell in table.get_celld().items():
      cell.set_facecolor("white")
      cell.set_edgecolor("none")
      cell.set_linewidth(0)

      if row == 0:
        cell.set_text_props(
            weight="bold",
            color="#222222"
      )

    for col in range(3):
      cell = table[(0, col)]
      cell.visible_edges = "TB"
      cell.set_linewidth(0.75)
      cell.set_edgecolor("#777777")

    global_row = len(table_data)

    for row in range(1, len(table_data)+1):
      risk = table_data[row-1][2]
      txt = table[(row,2)].get_text()
      txt.set_color(risk_colors[risk])
      txt.set_weight("bold")
      txt.set_fontsize(10)

    for col in range(3):
      cell = table[(global_row, col)]
      cell.visible_edges = "TB"
      cell.set_linewidth(0.75)
      cell.set_edgecolor("#777777")
      cell.set_text_props(weight="bold")

    table.auto_set_font_size(
        False
    )

    table.set_fontsize(
        9
    )

    table.scale(
        1,
        1.2
    )

    plt.tight_layout()

    if save:
      filename = (
          f"REBA_S{subject}_"
          f"{test_type}_"
          f"{phase}.png"
      )

      filepath = os.path.join(
          output_dir,
          filename
      )

      plt.savefig(
          filepath,
          dpi=600,
          bbox_inches="tight",
          facecolor="white"
      )

      print(f"Figura guardada en:\n{filepath}")
    plt.show()

