"""# **6.39. Reba comparación antes y despues PB vs PE**"""

def plot_reba_subject_comparison(
    kin_test_list,
    subject,
    save=False,
    output_dir=None
):
    """
    Comparación del perfil REBA entre Antes y Después
    para las condiciones PB y PE.

    Panel izquierdo : PB
    Panel derecho   : PE
    """

    subject = str(subject).zfill(2)

    pb_before = [
        t for t in kin_test_list
        if (
            t["subject"] == subject
            and t["test_type"] == "PB"
            and t["phase"] == "A"
        )
    ]

    pb_after = [
        t for t in kin_test_list
        if (
            t["subject"] == subject
            and t["test_type"] == "PB"
            and t["phase"] == "D"
        )
    ]

    pe_before = [
        t for t in kin_test_list
        if (
            t["subject"] == subject
            and t["test_type"] == "PE"
            and t["phase"] == "A"
        )
    ]

    pe_after = [
        t for t in kin_test_list
        if (
            t["subject"] == subject
            and t["test_type"] == "PE"
            and t["phase"] == "D"
        )
    ]

    if (
        len(pb_before) == 0
        or len(pb_after) == 0
        or len(pe_before) == 0
        or len(pe_after) == 0
    ):
        raise ValueError(
            "Faltan ensayos para construir la figura."
        )

    pb_before_profile = compute_average_reba_profile(
        pb_before
    )

    pb_after_profile = compute_average_reba_profile(
        pb_after
    )

    pe_before_profile = compute_average_reba_profile(
        pe_before
    )

    pe_after_profile = compute_average_reba_profile(
        pe_after
    )

    phase_limits_pb = compute_average_phase_boundaries(
        pb_before + pb_after
    )

    phase_limits_pe = compute_average_phase_boundaries(
        pe_before + pe_after
    )

    def smooth_profile(profile):

        mean = savgol_filter(
            profile["mean"],
            window_length=9,
            polyorder=2
        )

        ci95 = (
            1.96
            * profile["std"]
            / np.sqrt(profile["n"])
        )

        ci95 = savgol_filter(
            ci95,
            window_length=9,
            polyorder=2
        )

        return {
            "x": profile["x"],
            "mean": mean,
            "lower": mean - ci95,
            "upper": mean + ci95
        }

    pb_before_curve = smooth_profile(
        pb_before_profile
    )

    pb_after_curve = smooth_profile(
        pb_after_profile
    )

    pe_before_curve = smooth_profile(
        pe_before_profile
    )

    pe_after_curve = smooth_profile(
        pe_after_profile
    )

    fig, axs = plt.subplots(
        1,
        2,
        figsize=(18,7),
        sharex=True,
        sharey=True
    )

    ax_pb = axs[0]
    ax_pe = axs[1]

    risk_bands = [

        (1,4,"#DCEFD9"),

        (4,8,"#FFF3C4"),

        (8,11,"#FFD6A5"),

        (11,15,"#F8CACA")

    ]

    for ax in [ax_pb, ax_pe]:

        for y0, y1, color in risk_bands:

            ax.axhspan(
                y0,
                y1,
                color=color,
                alpha=0.55,
                zorder=0
            )

        for y in [4,8,11]:

            ax.axhline(
                y,
                color="#808080",
                ls="--",
                lw=1,
                alpha=0.6,
                zorder=1
            )

    add_phase_separators(
        ax_pb,
        phase_limits_pb
    )

    add_phase_separators(
        ax_pe,
        phase_limits_pe
    )

    color_before = "#264653"
    color_after = "#9C3D38"

    ax_pb.fill_between(
        pb_before_curve["x"],
        pb_before_curve["lower"],
        pb_before_curve["upper"],
        color=color_before,
        alpha=0.08,
        linewidth=0,
        zorder=2
    )

    ax_pb.plot(
        pb_before_curve["x"],
        pb_before_curve["mean"],
        color=color_before,
        linewidth=3.3,
        label="A (Antes)",
        zorder=5
    )

    ax_pb.fill_between(
        pb_after_curve["x"],
        pb_after_curve["lower"],
        pb_after_curve["upper"],
        color=color_after,
        alpha=0.08,
        linewidth=0,
        zorder=2
    )

    ax_pb.plot(
        pb_after_curve["x"],
        pb_after_curve["mean"],
        color=color_after,
        linewidth=3.3,
        label="D (Después)",
        zorder=5
    )

    ax_pe.fill_between(
        pe_before_curve["x"],
        pe_before_curve["lower"],
        pe_before_curve["upper"],
        color=color_before,
        alpha=0.08,
        linewidth=0,
        zorder=2
    )

    ax_pe.plot(
        pe_before_curve["x"],
        pe_before_curve["mean"],
        color=color_before,
        linewidth=3.3,
        label="Antes",
        zorder=5
    )

    ax_pe.fill_between(
        pe_after_curve["x"],
        pe_after_curve["lower"],
        pe_after_curve["upper"],
        color=color_after,
        alpha=0.08,
        linewidth=0,
        zorder=2
    )

    ax_pe.plot(
        pe_after_curve["x"],
        pe_after_curve["mean"],
        color=color_after,
        linewidth=3.3,
        label="Después",
        zorder=5
    )

    ax_pe.text(
        97, 2.5,
        "Bajo",
        ha="right",
        va="center",
        fontsize=10,
        color="#1B5E20",
        fontweight="bold"
    )

    ax_pe.text(
        97, 6,
        "Medio",
        ha="right",
        va="center",
        fontsize=10,
        color="#C68A00",
        fontweight="bold"
    )

    ax_pe.text(
        97, 9.5,
        "Alto",
        ha="right",
        va="center",
        fontsize=10,
        color="#CC6A00",
        fontweight="bold"
    )

    ax_pe.text(
        97, 13,
        "Muy alto",
        ha="right",
        va="center",
        fontsize=10,
        color="#B71C1C",
        fontweight="bold"
    )

    for ax in [ax_pb, ax_pe]:

        ax.set_xlim(0, 100)

        ax.set_ylim(1, 15)

        ax.grid(
            axis="y",
            alpha=0.30
        )

        ax.set_xlabel(
            "Movimiento normalizado (%)",
            fontsize=12
        )

        ax.spines["top"].set_visible(False)
        ax.spines["right"].set_visible(False)

    ax_pb.set_ylabel(
        "Puntuación REBA",
        fontsize=12,
        fontweight="bold"
    )

    ax_pb.set_title(
        "PB",
        fontsize=13,
        fontweight="bold",
        pad=6
    )

    ax_pe.set_title(
        "PE",
        fontsize=13,
        fontweight="bold",
        pad=6
    )

    handles, labels = ax_pb.get_legend_handles_labels()

    fig.legend(
        handles,
        labels,
        loc="upper center",
        ncol=2,
        frameon=False,
        fontsize=11,
        bbox_to_anchor=(0.5, 0.91)
    )

    fig.suptitle(
        f"Perfil promedio REBA · Sujeto {subject}",
        fontsize=16,
        fontweight="bold",
        y=0.99
    )

    fig.text(
        0.5,
        0.92,
        (
            "Comparación Antes vs Después · "
            "Línea: media · Banda: IC95% · "
            "Fondo: categorías de riesgo REBA"
        ),
        ha="center",
        fontsize=11,
        color="#666666"
    )

    plt.tight_layout(
        rect=[0, 0, 1, 0.92]
    )

    if save:

        filename = (
            f"REBA_Comparison_S{subject}.png"
        )

        filepath = os.path.join(
            output_dir,
            filename
        )

        plt.savefig(
            filepath,
            dpi=600,
            bbox_inches="tight",
            facecolor="white"
        )

        print(
            f"Figura guardada en:\n{filepath}"
        )
        plt.close(fig)

    else:

      plt.show()

