"""# **7.10. Procesamiento de pruebas EMG**"""

test_list = []

for filename, df_raw in datos.items():
    if not filename.endswith("_EMG.txt"):
        continue

    match = re.match(
        r"(\d{2})_(\d{2})_(PB|PE)_(A|D)_EMG\.txt",
        filename
    )

    if match is None:
        print(f"Nombre inválido: {filename}")
        continue

    try:
        emg_df, fs = prepare_emg(df_raw)

        result = preprocess_emg(
            emg_df,
            fs=fs
        )

        test_list.append({
            "id": match.group(1),
            "subject": match.group(2),
            "test_type": match.group(3),
            "phase": match.group(4),
            "df_filtered": result["filtered"],
            "df_envelope": result["envelope"],
            "fs": result["fs_target"]
        })

    except Exception as e:
        print(
            f"Error procesando "
            f"{filename}: {e}"
        )

