"""# **7.20. Gráficos de métricas por fase**"""

def plot_emg_metric_by_phase(
    df_phase_metrics,
    subject="01",
    test_type="PB",
    phase="A",
    metric="RMS"
):
    """
    Grafica una métrica EMG a través de las fases
    del movimiento.

    Parámetros
    ----------
    df_phase_metrics : pd.DataFrame

    subject : str
        Sujeto (ej. "01")

    test_type : str
        PB o PE

    phase : str
        A o D

    metric : str
        RMS, iEMG, MDF,
        relative_activation_%
    """

    df = df_phase_metrics[

        (df_phase_metrics["subject"] == subject)
        &
        (df_phase_metrics["test_type"] == test_type)
        &
        (df_phase_metrics["phase"] == phase)

    ].copy()

    if len(df) == 0:

        print("No hay datos.")
        return

    sns.set_theme(
        style="whitegrid",
        context="paper"
    )

    plt.figure(
        figsize=(9, 5)
    )

    muscles = sorted(
        df["muscle"].unique()
    )

    colors = sns.color_palette(
        "Dark2",
        len(muscles)
    )

    for muscle, color in zip(
        muscles,
        colors
    ):

        df_m = df[
            df["muscle"] == muscle
        ]

        df_m = df_m.sort_values(
            "movement_phase"
        )

        plt.plot(
            df_m["movement_phase"],
            df_m[metric],
            marker="o",
            linewidth=2.5,
            markersize=7,
            label=muscle.replace(
                " mV",
                ""
            ),
            color=color
        )

    plt.xticks(
        [1, 2, 3, 4],
        [
            "F1",
            "F2",
            "F3",
            "F4"
        ]
    )

    plt.xlabel(
        "Fase del movimiento",
        fontsize=11
    )

    plt.ylabel(
        metric,
        fontsize=11
    )

    plt.title(
        f"Sujeto {subject} · "
        f"{test_type} · "
        f"{phase}\n"
        f"{metric} por fase",
        fontsize=13,
        fontweight="semibold"
    )

    plt.legend(
        frameon=False,
        bbox_to_anchor=(1.02, 1),
        loc="upper left"
    )

    plt.tight_layout()

    plt.show()

