def plot_emg_phase_metrics_bar(
    df_phase_metrics,
    subject="01",
    test_type="PB",
    phase="A",
    save_path=None,
    dpi=600
):

    df = df_phase_metrics[

        (df_phase_metrics["subject"] == subject)
        &
        (df_phase_metrics["test_type"] == test_type)
        &
        (df_phase_metrics["phase"] == phase)

    ].copy()

    if len(df) == 0:

        print("No hay datos.")
        return

    sns.set_theme(
        style="whitegrid",
        context="paper"
    )

    mpl.rcParams.update({

        "font.family": "serif",

        "font.serif": [
            "Times New Roman",
            "STIXGeneral"
        ],

        "figure.facecolor": "white",

        "axes.facecolor": "#FCFCFC",

        "axes.edgecolor": "#D0D0D0",

        "axes.linewidth": 0.8,

        "grid.color": "#D6DCE5",

        "grid.linewidth": 0.6,

        "grid.alpha": 0.45,

        "xtick.color": "#606060",

        "ytick.color": "#606060",

        "savefig.dpi": 600
    })

    metrics = [

        "RMS",
        "iEMG",
        "MDF",
        "relative_activation_%"

    ]

    titles = {

        "RMS":
            "RMS (mV)",

        "iEMG":
            "iEMG (mV·s)",

        "MDF":
            "MDF (Hz)",

        "relative_activation_%":
            "Activación relativa (%)"
    }

    units = {

        "RMS": "µV",

        "iEMG": "µV·s",

        "MDF": "Hz",

        "relative_activation_%": "%"
    }

    muscles = [

        m for m in [

            "Trapecios mV",
            "Deltoides mV",
            "Triceps mV",
            "Biceps mV",
            "Escapulares mV"

        ]

        if m in df["muscle"].unique()

    ]

    muscle_labels = [

        m.replace(" mV", "")
         .replace("(mV)", "")
         .strip()

        for m in muscles

    ]

    colors = [

        "#1D3557",
        "#457B9D",
        "#2A9D8F",
        "#6A994E",
        "#4F6D7A"

    ]

    fig, axes = plt.subplots(

        2,
        2,

        figsize=(15, 9)

    )

    axes = axes.flatten()

    phases = [1, 2, 3, 4]

    x = np.arange(
        len(phases)
    )

    width = 0.15


    for ax, metric in zip(
        axes,
        metrics
        ):

        dominant_muscles = []

        for p in phases:
            phase_data = df[
                df["movement_phase"] == p
                ]

            idx_max = phase_data[metric].idxmax()

            dominant_muscles.append(
                phase_data.loc[idx_max, "muscle"]
        )


        for i, muscle in enumerate(
            muscles
            ):

            values = []

            for p in phases:

                subset = df[

                    (df["movement_phase"] == p)
                    &
                    (df["muscle"] == muscle)

                ]

                values.append(
                    subset[metric].mean()
                )

            for p_idx, value in enumerate(values):

              is_dominant = (
                  muscle == dominant_muscles[p_idx]
              )

              ax.bar(
                  x[p_idx] + (i - 2) * width,

                  value,

                  width,

                  color=colors[i],

                  alpha=0.95,

                  edgecolor=(
                      "white"
                      if is_dominant
                      else "white"
                  ),

                  linewidth=(
                      0.8
                      if is_dominant
                      else 0.8
                  ),

                  label=(
                      muscle_labels[i]
                      if p_idx == 0
                      else None
        )
    )

        if metric != "relative_activation_%":

            phase_mean = []
            phase_std = []

            for p in phases:

                vals = df[
                    df["movement_phase"] == p
                ][metric].values

                phase_mean.append(
                    np.mean(vals)
                )

                phase_std.append(
                    np.std(vals)
                )

            phase_mean = np.array(
                phase_mean
            )

            phase_std = np.array(
                phase_std
            )

            x_smooth = np.linspace(
                x.min(),
                x.max(),
                300
            )

            spline_mean = make_interp_spline(
                x,
                phase_mean,
                k=2
            )

            y_mean = spline_mean(
                x_smooth
            )

            spline_upper = make_interp_spline(
                x,
                phase_mean + phase_std,
                k=2
            )

            spline_lower = make_interp_spline(
                x,
                phase_mean - phase_std,
                k=2
            )

            y_upper = spline_upper(
                x_smooth
            )

            y_lower = spline_lower(
                x_smooth
            )

            ax.fill_between(

                x_smooth,

                y_lower,

                y_upper,

                color="#909090",

                alpha=0.15,

                zorder=1
            )

            ax.plot(

                x_smooth,

                y_mean,

                color="#101010",

                linewidth=3,

                zorder=5
            )

            ax.scatter(

                x,

                phase_mean,

                color="#101010",

                s=35,

                zorder=6
            )

            for xi, yi in zip(
                x,
                phase_mean
                ):
                ax.text(
                    xi,
                    yi + phase_std.max()*0.3,
                    f"{yi:.1f}",
                    fontsize=10,
                    ha="center",
                    va="bottom",
                    color="#303030"
                    )

        else:

          entropy_values = []

          for p_idx, p in enumerate(phases):

            phase_data = df[
                df["movement_phase"] == p
                ]

            activations = []

            for muscle in muscles:

               value = phase_data[
                   phase_data["muscle"] == muscle
               ]["relative_activation_%"].mean()
               activations.append(value)

            activations = np.array(
                activations
            )

            probs = activations / activations.sum()

            H = entropy(
                probs,
                base=2
            )

            entropy_values.append(H)

          ax2 = ax.twinx()
          ax2.grid(False)
          ax2.set_ylim(min(entropy_values) - 0.03,max(entropy_values) + 0.05)

          x_smooth_entropy = np.linspace(
              x.min(),
              x.max(),
              300
              )

          spline_entropy = make_interp_spline(
              x,
              entropy_values,
              k=2
              )

          y_entropy = spline_entropy(
              x_smooth_entropy)

          ax2.plot(
              x_smooth_entropy,
              y_entropy,
              "-",
              color="#000000",
              linestyle=(0, (4, 2)),
              linewidth=2.5,
              alpha=0.85,
              zorder=20
              )

          ax2.scatter(
              x,
              entropy_values,
              color="#000000",
              s=35,
              zorder=21
              )

          for xi, yi in zip(
              x,
              entropy_values
              ):

              ax2.text(
                  xi,
                  yi + 0.005,
                  f"{yi:.2f}",
                  ha="center",
                  fontsize=10,
                  color="#000000"
                  )

          ax2.set_ylabel(
              "Entropía (bits)",
              fontsize=9,
              color="#505050"
          )
          ax2.tick_params(
              axis="y",
              labelcolor="#505050"
          )

          ax2.tick_params(
              axis="y",
              colors="#505050"
          )

        ax.set_xticks(x)

        ax.set_xticklabels(

            ["F1", "F2", "F3", "F4"],

            fontsize=10
        )

        ax.set_title(

            titles[metric],

            fontsize=12,

            fontweight="semibold",

            color="#303030"
        )

        ax.set_ylabel(

            units[metric],

            fontsize=9,

            color="#505050"
        )

        ax.grid(

            axis="y",

            color="#D6DCE5",

            linewidth=0.6,

            alpha=0.45
        )

        ax.set_axisbelow(True)

        ax.spines["top"].set_visible(False)
        ax.spines["right"].set_visible(False)

        ax.spines["left"].set_color(
            "#D2D2D2"
        )

        ax.spines["bottom"].set_color(
            "#D2D2D2"
        )

    legend_handles = [
        Patch(
            facecolor=colors[i],
            edgecolor="white",
            label=muscle_labels[i]
            )

        for i in range(len(muscles))
        ]

    fig.legend(
        legend_handles,
        muscle_labels,
        loc="upper center",
        bbox_to_anchor=(0.5, 0.9),
        ncol=len(muscle_labels),
        frameon=False,
        fontsize=10
        )

    plt.tight_layout(

        rect=[0, 0, 1, 0.86]

    )

    if save_path is not None:

      os.makedirs(
          save_path,
          exist_ok=True
          )

      filename = os.path.join(
          save_path,
          f"{str(subject).zfill(2)}_"
          f"{test_type}_"
          f"{phase}_"
          f"PHASE_METRICS.png"
          )

      plt.savefig(

          filename,
          dpi=dpi,
          bbox_inches="tight",
          facecolor="white",
          edgecolor="none",
          format="png"
          )
      print(
          f"✔ Guardado: {filename}"
          )
      plt.close(fig)

    else:
      plt.show()

