import numpy as np
import pandas as pd
from IPython.display import display


def show_emg_phase_table(
    df_emg,
    subject="01",
    decimals=1,
    entropy_decimals=2
):
    """
    Muestra en Google Colab una tabla resumen de los parámetros EMG.

    RMS, iEMG y MDF:
        media ± desviación estándar entre músculos.

    Entropía:
        entropía de Shannon de la distribución de activación muscular,
        sin desviación estándar.
    """

    phases = [1, 2, 3, 4]

    conditions = [
        ("PB", "A"),
        ("PB", "D"),
        ("PE", "A"),
        ("PE", "D")
    ]

    muscles = [
        "Trapecios mV",
        "Deltoides mV",
        "Triceps mV",
        "Biceps mV",
        "Escapulares mV"
    ]

    metrics = ["RMS", "iEMG", "MDF"]

    rows = []

    def mean_sd(values):

        values = pd.Series(values).dropna().astype(float)

        if len(values) == 0:
            return "--"

        mean = values.mean()

        if len(values) > 1:
            sd = values.std(ddof=1)
        else:
            sd = 0.0

        return (
            f"{mean:.{decimals}f} ± "
            f"{sd:.{decimals}f}"
        )

    for test_type, moment in conditions:

        for metric in metrics:

            row = {
                "Prueba": test_type,
                "Momento": moment,
                "Parámetro": metric
            }

            for phase in phases:

                subset = df_emg[
                    (df_emg["subject"] == subject) &
                    (df_emg["test_type"] == test_type) &
                    (df_emg["phase"] == moment) &
                    (df_emg["movement_phase"] == phase)
                ].copy()

                subset = subset[
                    subset["muscle"].isin(muscles)
                ]

                if len(subset) == 0:
                    value = "--"

                else:
                    value = mean_sd(
                        subset[metric]
                    )

                row[f"F{phase}"] = value

            rows.append(row)

        row = {
            "Prueba": test_type,
            "Momento": moment,
            "Parámetro": "Entropía (bits)"
        }

        for phase in phases:

            subset = df_emg[
                (df_emg["subject"] == subject) &
                (df_emg["test_type"] == test_type) &
                (df_emg["phase"] == moment) &
                (df_emg["movement_phase"] == phase)
            ].copy()

            subset = subset[
                subset["muscle"].isin(muscles)
            ]

            if (
                len(subset) == 0 or
                "relative_activation_%" not in subset.columns
            ):

                row[f"F{phase}"] = "--"
                continue

            activations = []

            for muscle in muscles:

                muscle_values = subset[
                    subset["muscle"] == muscle
                ]["relative_activation_%"]

                if len(muscle_values) > 0:
                    value = muscle_values.mean()
                else:
                    value = 0.0

                activations.append(value)

            activations = np.asarray(
                activations,
                dtype=float
            )

            total = activations.sum()

            if total <= 0:

                row[f"F{phase}"] = "--"
                continue

            probabilities = activations / total

            probabilities = probabilities[
                probabilities > 0
            ]

            H = -np.sum(
                probabilities *
                np.log2(probabilities)
            )

            row[f"F{phase}"] = (
                f"{H:.{entropy_decimals}f}"
            )

        rows.append(row)

    table = pd.DataFrame(rows)

    table = table[
        [
            "Prueba",
            "Momento",
            "Parámetro",
            "F1",
            "F2",
            "F3",
            "F4"
        ]
    ]

    display(table)

    return table

tabla_emg = show_emg_phase_table(
    df_emg=df_phase_metrics,
    subject="03"
)

"""# **7.25. Gráficos de calor por fase**"""

def plot_emg_phase_heatmaps(
    df_phase_metrics,
    subject="01",
    test_type="PB",
    phase="A"
):
    """
    Heatmaps EMG estilo tesis/publicación científica.

    Mejoras:
    - Orden muscular fijo.
    - Pico global resaltado.
    - Identificación automática del pico.
    - Contraste automático de texto.
    - Diseño limpio para tesis.
    """

    df = df_phase_metrics[

        (df_phase_metrics["subject"] == subject)
        &
        (df_phase_metrics["test_type"] == test_type)
        &
        (df_phase_metrics["phase"] == phase)

    ].copy()

    if len(df) == 0:

        print("No hay datos.")
        return

    sns.set_theme(
        style="white",
        context="paper"
    )

    mpl.rcParams.update({

        "font.family": "serif",

        "font.serif": [
            "Times New Roman",
            "STIXGeneral"
        ],

        "figure.facecolor": "white",

        "axes.facecolor": "white",

        "axes.edgecolor": "#D0D0D0",

        "xtick.labelsize": 10,

        "ytick.labelsize": 10,

        "savefig.dpi": 600
    })

    metrics = [

        "RMS",
        "iEMG",
        "MDF",
        "relative_activation_%"

    ]

    titles = {

        "RMS":
            "A | RMS",

        "iEMG":
            "B | iEMG",

        "MDF":
            "C | MDF",

        "relative_activation_%":
            "D | Activación relativa (%)"
    }

    units = {

        "RMS": "µV",

        "iEMG": "µV·s",

        "MDF": "Hz",

        "relative_activation_%": "%"
    }

    formats = {

        "RMS": ".1f",

        "iEMG": ".0f",

        "MDF": ".0f",

        "relative_activation_%": ".0f"
    }

    muscle_order = [

        "Escapulares",
        "Deltoides",
        "Triceps",
        "Trapecios",
        "Biceps"

    ]

    fig, axes = plt.subplots(

        2,
        2,

        figsize=(15, 9)

    )

    axes = axes.flatten()

    cmap = sns.color_palette(
        "mako",
        as_cmap=True
    )

    for ax, metric in zip(
        axes,
        metrics
    ):

        heatmap_data = (

            df.groupby(
                [
                    "muscle",
                    "movement_phase"
                ]
            )[metric]

            .mean()

            .unstack()

        )

        heatmap_data.index = [

            str(m)
            .replace(" mV", "")
            .replace("(mV)", "")
            .strip()

            for m in heatmap_data.index

        ]

        existing_order = [

            m for m in muscle_order
            if m in heatmap_data.index

        ]

        heatmap_data = heatmap_data.reindex(
            existing_order
        )

        annot_data = heatmap_data.copy()

        for r in range(
            annot_data.shape[0]
        ):

            for c in range(
                annot_data.shape[1]
            ):

                value = annot_data.iloc[r, c]

                if pd.isna(value):

                    annot_data.iloc[r, c] = ""

                else:

                    annot_data.iloc[r, c] = (
                        f"{value:{formats[metric]}}"
                    )

        hm = sns.heatmap(

            heatmap_data,

            cmap=cmap,

            annot=annot_data,

            fmt="",

            linewidths=1,

            linecolor="#F1F1F1",

            cbar=True,

            square=False,

            ax=ax,

            annot_kws={

                "fontsize": 10,

                "fontweight": "bold"
            }

        )

        vmin = np.nanmin(
            heatmap_data.values
        )

        vmax = np.nanmax(
            heatmap_data.values
        )

        if vmin == vmax:

            vmax += 1e-9

        norm = mpl.colors.Normalize(

            vmin=vmin,

            vmax=vmax

        )

        text_counter = 0

        for r in range(
            heatmap_data.shape[0]
        ):

            for c in range(
                heatmap_data.shape[1]
            ):

                value = heatmap_data.iloc[r, c]

                if pd.isna(value):

                    continue

                text = hm.texts[text_counter]

                text_counter += 1

                rr, gg, bb, _ = cmap(
                    norm(value)
                )

                luminance = (

                    0.299 * rr
                    +
                    0.587 * gg
                    +
                    0.114 * bb

                )

                if luminance < 0.55:

                    text.set_color(
                        "white"
                    )

                else:

                    text.set_color(
                        "#202020"
                    )

        max_idx = np.unravel_index(

            np.nanargmax(
                heatmap_data.values
            ),

            heatmap_data.shape

        )

        peak_muscle = heatmap_data.index[
            max_idx[0]
        ]

        peak_phase = heatmap_data.columns[
            max_idx[1]
        ]

        ax.add_patch(

            plt.Rectangle(

                (

                    max_idx[1],
                    max_idx[0]

                ),

                1,
                1,

                fill=False,

                edgecolor="gold",

                linewidth=2.8

            )

        )

        ax.scatter(

            -0.012,

            1.08,

            s=65,

            marker="s",

            color="#1D3557",

            transform=ax.transAxes,

            clip_on=False

        )

        ax.text(

            0.03,

            1.075,

            titles[metric],

            transform=ax.transAxes,

            fontsize=12,

            fontweight="semibold",

            color="#303030",

            va="center"

        )

        ax.text(

            0.03,

            1.015,

            f"Pico: {peak_muscle} (F{peak_phase})",

            transform=ax.transAxes,

            fontsize=8.5,

            color="#707070"

        )

        ax.set_xlabel("")
        ax.set_ylabel("")

        xticklabels = []

        for tick in ax.get_xticklabels():

            try:

                xticklabels.append(
                    f"F{int(float(tick.get_text()))}"
                )

            except:

                xticklabels.append(
                    tick.get_text()
                )

        ax.set_xticklabels(

            xticklabels,

            fontsize=10,

            rotation=0

        )

        ax.set_yticklabels(

            ax.get_yticklabels(),

            fontsize=11,

            rotation=0

        )

        ax.tick_params(
            length=0
        )

        cbar = hm.collections[0].colorbar

        cbar.ax.tick_params(
            labelsize=9
        )

        cbar.outline.set_visible(
            False
        )

        cbar.ax.set_ylabel(

            units[metric],

            rotation=0,

            fontsize=9,

            labelpad=12,

            color="#707070"

        )

        for spine in ax.spines.values():

            spine.set_visible(
                False
            )

    fig.suptitle(

        f"Sujeto {subject} · "
        f"{test_type} · "
        f"{phase}",

        fontsize=19,

        fontweight="semibold",

        color="#202020",

        y=0.93

    )

    fig.text(

        0.5,

        0.88,

        (
            "Distribución espacial de métricas EMG "
            "a través de las fases del movimiento"
        ),

        ha="center",

        fontsize=10,

        color="#707070"
    )

    fig.subplots_adjust(

        top=0.82,

        hspace=0.24,

        wspace=0.18

    )

    plt.show()

