"""# **7.27. Calcular perfil promedio EMG**"""

def compute_average_emg_profile(
    tests,
    muscle,
    n_points=101
):
    """
    Calcula el perfil promedio EMG para un músculo,
    utilizando únicamente las pruebas donde existe.
    """

    normalized_signals = []

    for test in tests:

        df = test["df_envelope"]

        if muscle not in df.columns:
            continue

        signal = df[muscle].values

        normalized = normalize_signal(
            signal,
            n_points=n_points
        )

        normalized_signals.append(
            normalized
        )

    if len(normalized_signals) == 0:

        raise ValueError(
            f"No se encontraron ensayos para: {muscle}"
        )

    normalized_signals = np.array(
        normalized_signals
    )

    mean_profile = np.mean(
        normalized_signals,
        axis=0
    )

    if normalized_signals.shape[0] > 1:

        std_profile = np.std(
            normalized_signals,
            axis=0,
            ddof=1
        )

    else:

        std_profile = np.zeros_like(
            mean_profile
        )

    x = np.linspace(
        0,
        100,
        n_points
    )

    return {
        "x": x,
        "mean": mean_profile,
        "std": std_profile,
        "all_signals": normalized_signals,
        "n_trials": normalized_signals.shape[0]
    }

"""# **7.28. Calcular límites promedio**"""

def compute_average_emg_phase_boundaries(
    tests,
    phase_intervals_dict
):
    """
    Calcula los límites promedio de fase para
    una condición EMG.

    Retorna
    -------
    dict
        {
            1: ...,
            2: ...,
            3: ...
        }
    """

    phase1_end = []
    phase2_end = []
    phase3_end = []

    for test in tests:

        key = (
            test["subject"],
            test["id"],
            test["test_type"],
            test["phase"]
        )

        if key not in phase_intervals_dict:
            continue

        intervals = phase_intervals_dict[key]

        duration = (
            test["df_envelope"]["tiempo"]
            .iloc[-1]
        )

        phase1_end.append(
            100 * intervals[1][1] / duration
        )

        phase2_end.append(
            100 * intervals[2][1] / duration
        )

        phase3_end.append(
            100 * intervals[3][1] / duration
        )

    return {

        1: np.mean(phase1_end),

        2: np.mean(phase2_end),

        3: np.mean(phase3_end)
    }

"""# **7.29. Graficar perfil promedio EMG**"""

def plot_average_emg_signal(
    ax,
    x,
    mean_signal,
    std_signal,
    title,
    color,
    phase_limits=None,
    n_trials=None
):
    """
    Grafica un perfil promedio EMG
    con banda de desviación estándar.

    Parámetros
    ----------
    ax : matplotlib.axes.Axes
        Eje de destino.
    x : array-like
        Eje normalizado (0-100%).
    mean_signal : array-like
        Activación promedio.
    std_signal : array-like
        Desviación estándar.
    title : str
        Nombre del músculo.
    color : tuple
        Color de la señal.
    phase_limits : dict, opcional
        Límites promedio de fase.
    n_trials : int, opcional
        Número de ensayos usados.
    """

    if phase_limits is not None:

        add_average_phase_background(
            ax,
            phase_limits
        )

    upper = mean_signal + std_signal
    lower = np.maximum(
        mean_signal - std_signal,
        0
    )

    y_min = 0

    y_max = np.max(
        upper
    )

    padding = max(
        5,
        0.08 * y_max
    )

    ax.set_ylim(
        y_min,
        y_max + padding
    )

    ax.fill_between(
        x,
        lower,
        upper,
        color=color,
        alpha=0.18,
        linewidth=0
    )

    ax.plot(
        x,
        mean_signal,
        color=color,
        linewidth=2.4,
        alpha=0.98
    )

    if n_trials is not None:

        label = (
            f"{title} "
            f"(n={n_trials})"
        )

    else:

        label = title

    ax.text(
        0.02,
        1.055,
        "■",
        transform=ax.transAxes,
        fontsize=12,
        color=color,
        va="center"
    )

    ax.text(
        0.075,
        1.05,
        label,
        transform=ax.transAxes,
        fontsize=10,
        fontweight="semibold",
        color="#303030",
        va="center"
    )

    ax.grid(
        which="major",
        color="#D6DCE5",
        linewidth=0.6,
        alpha=0.50
    )

    ax.minorticks_on()

    ax.grid(
        which="minor",
        color="#ECEFF4",
        linewidth=0.4,
        alpha=0.12
    )

    ax.spines["top"].set_visible(False)
    ax.spines["right"].set_visible(False)

    ax.spines["left"].set_color("#D2D2D2")
    ax.spines["bottom"].set_color("#D2D2D2")

    ax.tick_params(
        axis="both",
        which="major",
        length=3,
        width=0.6,
        color="#707070"
    )

    ax.tick_params(
        axis="both",
        which="minor",
        length=2,
        width=0.4,
        color="#B0B0B0"
    )

    ax.yaxis.set_major_locator(
        MaxNLocator(5)
    )

    ax.margins(x=0)

    ax.set_ylabel(
        "Activación (%)",
        fontsize=9,
        color="#404040"
    )

    ax.set_xlabel(
        "% del movimiento",
        fontsize=9,
        color="#404040"
    )

