"""# **7.30. Graficar comparación global de músculos**"""

def plot_global_emg_profile(
    ax,
    profiles,
    muscle_labels,
    colors,
    phase_limits=None
):
    """
    Grafica todas las medias musculares
    en un único panel.

    No muestra bandas de desviación estándar.
    """

    if phase_limits is not None:

        add_average_phase_background(
            ax,
            phase_limits
        )

    y_max = 0

    for muscle, color in zip(
        muscle_labels.keys(),
        colors
    ):

        if muscle not in profiles:
            continue

        profile = profiles[muscle]

        ax.plot(
            profile["x"],
            profile["mean"],
            color=color,
            linewidth=2.3,
            alpha=0.95,
            label=muscle_labels[muscle]
        )

        y_max = max(
            y_max,
            np.max(profile["mean"])
        )

    ax.set_ylim(
        0,
        y_max * 1.15
    )

    ax.text(
        0.075,
        1.05,
        "Comparación muscular",
        transform=ax.transAxes,
        fontsize=10,
        fontweight="semibold",
        color="#303030",
        va="center"
        )

    ax.text(
        0.075,
        1.05,
        "Comparación muscular",
        transform=ax.transAxes,
        fontsize=10,
        fontweight="semibold",
        color="#303030",
        va="center"
    )

    ax.legend(
        loc="center left",
        bbox_to_anchor=(1.02, 0.5),
        frameon=False,
        fontsize=8
        )

    ax.grid(
        which="major",
        color="#D6DCE5",
        linewidth=0.6,
        alpha=0.50
    )

    ax.minorticks_on()

    ax.grid(
        which="minor",
        color="#ECEFF4",
        linewidth=0.4,
        alpha=0.12
    )

    ax.spines["top"].set_visible(False)
    ax.spines["right"].set_visible(False)

    ax.spines["left"].set_color("#D2D2D2")
    ax.spines["bottom"].set_color("#D2D2D2")

    ax.tick_params(
        axis="both",
        which="major",
        length=3,
        width=0.6,
        color="#707070"
    )

    ax.tick_params(
        axis="both",
        which="minor",
        length=2,
        width=0.4,
        color="#B0B0B0"
    )

    ax.yaxis.set_major_locator(
        MaxNLocator(5)
    )

    ax.margins(x=0)

    ax.set_ylabel(
        "Activación (%)",
        fontsize=9,
        color="#404040"
    )

    ax.set_xlabel(
        "% del movimiento",
        fontsize=9,
        color="#404040"
    )

"""# **7.31. Graficar perfil promedio EMG**"""

def plot_average_emg_analysis(
    test_list,
    phase_intervals_dict,
    subject,
    test_type,
    phase,
    save_path=None
):
    """
    Genera el perfil promedio EMG para una condición.

    Parámetros
    ----------
    test_list : list
        Lista completa de pruebas EMG.
    phase_intervals_dict : dict
        Diccionario con intervalos de fase proyectados.
    subject : str
        Identificador del sujeto.
    test_type : str
        PB o PE.
    phase : str
        A o D.
    save_path : str, opcional
        Directorio de exportación.

    Retorna
    -------
    None
    """

    tests = [

        test

        for test in test_list

        if (
            test["subject"] == str(subject).zfill(2)
            and
            test["test_type"] == test_type
            and
            test["phase"] == phase
        )
    ]

    if len(tests) == 0:

        raise ValueError(
            "No se encontraron pruebas para la condición."
        )

    phase_limits = (
        compute_average_emg_phase_boundaries(
            tests,
            phase_intervals_dict
        )
    )

    muscle_order = [
        "Trapecios mV",
        "Deltoides mV",
        "Triceps mV",
        "Biceps mV",
        "Escapulares mV"
    ]

    muscle_labels = {
        "Trapecios mV": "Trapecio superior",
        "Deltoides mV": "Deltoides anterior",
        "Triceps mV": "Tríceps braquial",
        "Biceps mV": "Bíceps braquial",
        "Escapulares mV": "Escapulares"
    }

    profiles = {}

    for muscle in muscle_order:

        try:

            profiles[muscle] = (
                compute_average_emg_profile(
                    tests,
                    muscle
                )
            )

        except ValueError:

            continue

    sns.set_theme(
        style="whitegrid",
        context="paper",
        font_scale=1.10
    )

    mpl.rcParams.update({
        "font.family": "serif",
        "font.serif": ["Times New Roman", "STIXGeneral"],
        "mathtext.fontset": "stix",
        "figure.facecolor": "white",
        "axes.facecolor": "#FCFCFC",
        "axes.linewidth": 0.8,
        "axes.edgecolor": "#D3D3D3",
        "grid.color": "#D6DCE5",
        "grid.linewidth": 0.7,
        "grid.alpha": 0.55,
        "xtick.color": "#707070",
        "ytick.color": "#707070",
        "xtick.labelsize": 8,
        "ytick.labelsize": 8,
        "figure.dpi": 220,
        "savefig.dpi": 1200
    })

    colors = sns.color_palette(
        "mako",
        5
    )

    fig = plt.figure(
        figsize=(14, 10)
    )

    ax1 = plt.subplot2grid(
        (3, 2),
        (0, 0)
    )

    ax2 = plt.subplot2grid(
        (3, 2),
        (0, 1)
    )

    ax3 = plt.subplot2grid(
        (3, 2),
        (1, 0)
    )

    ax4 = plt.subplot2grid(
        (3, 2),
        (1, 1)
    )

    ax5 = plt.subplot2grid(
        (3, 2),
        (2, 0),
        colspan=2
    )

    axes = [
        ax1,
        ax2,
        ax3,
        ax4,
        ax5
    ]

    for idx, muscle in enumerate(muscle_order):

        if muscle not in profiles:
            continue

        profile = profiles[muscle]

        plot_average_emg_signal(
            axes[idx],
            profile["x"],
            profile["mean"],
            profile["std"],
            muscle_labels[muscle],
            colors[idx],
            phase_limits,
            profile["n_trials"]
        )

    fig.suptitle(
        f"Perfil Promedio de Activación Muscular · "
        f"Sujeto {subject} · "
        f"{test_type} · "
        f"{phase}",
        fontsize=14,
        fontweight="semibold",
        y=0.98
    )

    fig.text(
        0.5,
        0.94,
        f"Promedio de {len(tests)} ensayos EMG normalizados",
        ha="center",
        fontsize=9,
        color="#707070"
    )

    phase_legend = [

        Patch(
            facecolor="#DCEEFF",
            edgecolor="none",
            alpha=0.6,
            label="Fase 1"
        ),

        Patch(
            facecolor="#DDF7E3",
            edgecolor="none",
            alpha=0.6,
            label="Fase 2"
        ),

        Patch(
            facecolor="#FFF3D6",
            edgecolor="none",
            alpha=0.6,
            label="Fase 3"
        ),

        Patch(
            facecolor="#FFE0E0",
            edgecolor="none",
            alpha=0.6,
            label="Fase 4"
        )
    ]

    fig.legend(
        handles=phase_legend,
        loc="upper center",
        bbox_to_anchor=(0.5, 0.92),
        ncol=4,
        frameon=False,
        fontsize=9
    )

    plt.subplots_adjust(
        left=0.065,
        right=0.985,
        bottom=0.070,
        top=0.88,
        hspace=0.45,
        wspace=0.22
    )

    if save_path is not None:

        os.makedirs(
            save_path,
            exist_ok=True
        )

        filename = os.path.join(

            save_path,

            f"S{int(subject):02d}_"
            f"{test_type}_"
            f"{phase}_"
            f"_EMG_AVERAGE.png"
        )

        plt.savefig(
            filename,
            dpi=600,
            bbox_inches="tight",
            facecolor="white",
            edgecolor="none",
            format="png"
        )

        print(
            f"✔ Guardado: {filename}"
        )

        plt.close(fig)

    else:

        plt.show()

