def plot_average_emg_signal_comparison(
    ax,
    x,
    mean_signal,
    std_signal,
    color,
    phase_limits=None,
    ylim=None,
    muscle_name=None,
    show_ylabel=False,
    show_xlabel=False
):
    """
    Dibuja un perfil promedio EMG para la figura
    Antes vs Después.
    """

    if phase_limits is not None:

        add_average_phase_background(
            ax,
            phase_limits
        )

    upper = mean_signal + std_signal

    lower = np.maximum(
        mean_signal - std_signal,
        0
    )

    ax.fill_between(
        x,
        lower,
        upper,
        color=color,
        alpha=0.18,
        linewidth=0
    )

    ax.plot(
        x,
        mean_signal,
        color=color,
        linewidth=1.8
    )

    if ylim is not None:

        ax.set_ylim(ylim)

    ax.grid(
        which="major",
        color="#D6DCE5",
        linewidth=0.6,
        alpha=0.50
    )

    ax.minorticks_on()

    ax.grid(
        which="minor",
        color="#ECEFF4",
        linewidth=0.4,
        alpha=0.12
    )

    ax.spines["top"].set_visible(False)
    ax.spines["right"].set_visible(False)

    ax.spines["left"].set_color("#D2D2D2")
    ax.spines["bottom"].set_color("#D2D2D2")

    ax.tick_params(
        axis="both",
        which="major",
        length=3,
        width=0.6,
        color="#707070",
        labelsize=8
    )

    ax.tick_params(
        axis="both",
        which="minor",
        length=2,
        width=0.4,
        color="#B0B0B0"
    )

    ax.yaxis.set_major_locator(
        MaxNLocator(5)
    )

    ax.margins(x=0)

    if muscle_name is not None:

      ax.text(
          -0.20,            # posición horizontal (fuera del eje)
          0.50,             # mitad vertical
          muscle_name,
          transform=ax.transAxes,
          fontsize=10,
          fontweight="bold",
          ha="right",
          va="center"
          )

    if show_ylabel:

        ax.set_ylabel(
            "Activación (%)",
            fontsize=9
        )

    else:

        ax.set_ylabel("")

    if show_xlabel:

        ax.set_xlabel(
            "% del movimiento",
            fontsize=9
        )

    else:

        ax.set_xlabel("")
        ax.set_xticklabels([])

def plot_average_emg_before_after_analysis(
    test_list,
    phase_intervals_dict,
    subject,
    test_type,
    save_path=None
):
    """
    Genera una figura de comparación Antes vs Después
    para un sujeto y un tipo de movimiento.
    """

    tests_before = [

        test

        for test in test_list

        if (
            test["subject"] == str(subject).zfill(2)
            and
            test["test_type"] == test_type
            and
            test["phase"] == "A"
        )
    ]

    tests_after = [

        test

        for test in test_list

        if (
            test["subject"] == str(subject).zfill(2)
            and
            test["test_type"] == test_type
            and
            test["phase"] == "D"
        )
    ]

    if len(tests_before) == 0:

        raise ValueError(
            "No existen pruebas Antes."
        )

    if len(tests_after) == 0:

        raise ValueError(
            "No existen pruebas Después."
        )

    phase_before = compute_average_emg_phase_boundaries(
        tests_before,
        phase_intervals_dict
    )

    phase_after = compute_average_emg_phase_boundaries(
        tests_after,
        phase_intervals_dict
    )

    muscle_order = [

        "Trapecios mV",
        "Deltoides mV",
        "Triceps mV",
        "Biceps mV",
        "Escapulares mV"

    ]

    muscle_labels = {

        "Trapecios mV": "Trapecio superior",

        "Deltoides mV": "Deltoides anterior",

        "Triceps mV": "Tríceps braquial",

        "Biceps mV": "Bíceps braquial",

        "Escapulares mV": "Escapulares"

    }

    sns.set_theme(

        style="whitegrid",
        context="paper",
        font_scale=1.10

    )

    mpl.rcParams.update({

        "font.family": "serif",

        "font.serif": ["Times New Roman", "STIXGeneral"],

        "mathtext.fontset": "stix",

        "figure.facecolor": "white",

        "axes.facecolor": "#FCFCFC",

        "axes.linewidth": 0.8,

        "axes.edgecolor": "#D3D3D3",

        "grid.color": "#D6DCE5",

        "grid.linewidth": 0.7,

        "grid.alpha": 0.55,

        "xtick.color": "#707070",

        "ytick.color": "#707070",

        "xtick.labelsize": 8,

        "ytick.labelsize": 8,

        "figure.dpi": 220,

        "savefig.dpi": 1200

    })

    colors = sns.color_palette(
        "mako",
        5
    )

    fig, axes = plt.subplots(

        5,
        2,

        figsize=(10, 13),

        sharex=True

    )

    axes = np.array(axes)

    axes[0,0].set_title(
        "Antes",
        fontsize=12,
        fontweight="bold",
        pad=12
    )

    axes[0,1].set_title(
        "Después",
        fontsize=12,
        fontweight="bold",
        pad=12
    )

    for row, muscle in enumerate(muscle_order):

        try:

            profile_before = compute_average_emg_profile(
                tests_before,
                muscle
            )

            profile_after = compute_average_emg_profile(
                tests_after,
                muscle
            )

        except ValueError:

            continue

        upper_before = np.max(
            profile_before["mean"] +
            profile_before["std"]
        )

        upper_after = np.max(
            profile_after["mean"] +
            profile_after["std"]
        )

        ymax = max(
            upper_before,
            upper_after
        )

        ylim = (
            0,
            ymax * 1.08
        )

        plot_average_emg_signal_comparison(

            ax=axes[row, 0],

            x=profile_before["x"],

            mean_signal=profile_before["mean"],

            std_signal=profile_before["std"],

            color=colors[row],

            phase_limits=phase_before,

            ylim=ylim,

            muscle_name=muscle_labels[muscle],

            show_ylabel=True,

            show_xlabel=(row == len(muscle_order)-1)

        )

        plot_average_emg_signal_comparison(

            ax=axes[row, 1],

            x=profile_after["x"],

            mean_signal=profile_after["mean"],

            std_signal=profile_after["std"],

            color=colors[row],

            phase_limits=phase_after,

            ylim=ylim,

            muscle_name=None,

            show_ylabel=False,

            show_xlabel=(row == len(muscle_order)-1)

        )

subjects = ["01", "02", "03"]
test_types = ["PB", "PE"]

for subject in subjects:

    for test_type in test_types:

        print(f"Sujeto {subject} - {test_type}")

        plot_average_emg_before_after_analysis(
            test_list=test_list,
            phase_intervals_dict=phase_intervals_dict,
            subject=subject,
            test_type=test_type
        )

def plot_average_emg_signal_dual(
    ax,
    profile_pb,
    profile_pe,
    color_pb="royalblue",
    color_pe="crimson",
    phase_limits=None,
    ylim=None,
    muscle_name=None,
    show_ylabel=False,
    show_xlabel=False
):
    """
    Dibuja en un mismo eje los perfiles promedio de EMG para:
        - Movimiento Básico (PB)
        - Movimiento Extremo (PE)

    No modifica la amplitud de la señal.
    El eje X corresponde únicamente al porcentaje del movimiento.
    """
    if phase_limits is not None:
        add_average_phase_background(ax, phase_limits)

    ax.fill_between(
        profile_pb["x"],
        profile_pb["mean"] - profile_pb["std"],
        profile_pb["mean"] + profile_pb["std"],
        color=color_pb,
        alpha=0.10
    )

    ax.plot(
        profile_pb["x"],
        profile_pb["mean"],
        color=color_pb,
        linewidth=1.8,
        linestyle="-",
        label="PB"
    )

    ax.fill_between(
        profile_pe["x"],
        profile_pe["mean"] - profile_pe["std"],
        profile_pe["mean"] + profile_pe["std"],
        color=color_pe,
        alpha=0.10
    )

    ax.plot(
        profile_pe["x"],
        profile_pe["mean"],
        color=color_pe,
        linewidth=1.8,
        linestyle="--",
        label="PE"
    )

    ax.set_xlim(profile_pb["x"][0], profile_pb["x"][-1])

    if ylim is not None:
        ax.set_ylim(ylim)

    if muscle_name is not None:

        ax.text(
            -0.20,
            0.50,
            muscle_name,
            transform=ax.transAxes,
            fontsize=10,
            fontweight="bold",
            rotation=90,
            ha="right",
            va="center"
        )

    if show_xlabel:
        ax.set_xlabel("% del movimiento", fontsize=10)
    else:
        ax.tick_params(axis="x", labelbottom=False)

    ax.grid(
        which="major",
        color="#D6DCE5",
        linewidth=0.6,
        alpha=0.50
    )

    ax.minorticks_on()

    ax.grid(
        which="minor",
        color="#ECEFF4",
        linewidth=0.4,
        alpha=0.12
    )

    ax.spines["top"].set_visible(False)
    ax.spines["right"].set_visible(False)
    ax.spines["left"].set_color("#D2D2D2")
    ax.spines["bottom"].set_color("#D2D2D2")

    ax.tick_params(
        axis="both",
        which="major",
        length=3,
        width=0.6,
        color="#707070",
        labelsize=8
        )
    ax.tick_params(
        axis="both",
        which="minor",
        length=2,
        width=0.4,
        color="#B0B0B0"
        )

def plot_average_emg_subject_comparison(
    test_list,
    phase_intervals_dict,
    subject,
    save_path=None
):
    """
    Genera una figura con la comparación PB vs PE
    para un sujeto, antes y después del entrenamiento.
    """

    pb_before = [
        t for t in test_list
        if t["subject"] == subject
        and t["test_type"] == "PB"
        and t["phase"] == "A"
    ]

    pb_after = [
        t for t in test_list
        if t["subject"] == subject
        and t["test_type"] == "PB"
        and t["phase"] == "D"
    ]

    pe_before = [
        t for t in test_list
        if t["subject"] == subject
        and t["test_type"] == "PE"
        and t["phase"] == "A"
    ]

    pe_after = [
        t for t in test_list
        if t["subject"] == subject
        and t["test_type"] == "PE"
        and t["phase"] == "D"
    ]

    phase_before = compute_average_emg_phase_boundaries(
        pb_before + pe_before,
        phase_intervals_dict
    )

    phase_after = compute_average_emg_phase_boundaries(
        pb_after + pe_after,
        phase_intervals_dict
    )

    muscle_order = [
        "Trapecios mV",
        "Deltoides mV",
        "Triceps mV",
        "Biceps mV",
        "Escapulares mV"
    ]

    muscle_labels = {
        "Trapecios mV": "Trapecio",
        "Deltoides mV": "Deltoides",
        "Triceps mV": "Tríceps",
        "Biceps mV": "Bíceps",
        "Escapulares mV": "Escapulares"
    }

    fig, axes = plt.subplots(
        nrows=5,
        ncols=2,
        figsize=(10, 10),
        sharex=True
    )

    axes[0, 0].set_title("A (Antes)", fontsize=12, fontweight="bold")
    axes[0, 1].set_title("D (Después)", fontsize=12, fontweight="bold")

    for row, muscle in enumerate(muscle_order):

        profile_pb_before = compute_average_emg_profile(
            pb_before,
            muscle
        )

        profile_pb_after = compute_average_emg_profile(
            pb_after,
            muscle
        )

        profile_pe_before = compute_average_emg_profile(
            pe_before,
            muscle
        )

        profile_pe_after = compute_average_emg_profile(
            pe_after,
            muscle
        )

        ymax = max(
            np.max(profile_pb_before["mean"] + profile_pb_before["std"]),
            np.max(profile_pb_after["mean"] + profile_pb_after["std"]),
            np.max(profile_pe_before["mean"] + profile_pe_before["std"]),
            np.max(profile_pe_after["mean"] + profile_pe_after["std"])
        )

        ylim = (0, ymax * 1.10)

        plot_average_emg_signal_dual(
            ax=axes[row, 0],
            profile_pb=profile_pb_before,
            profile_pe=profile_pe_before,
            color_pb="#3E6488",
            color_pe="#C44E52",
            phase_limits=phase_before,
            ylim=ylim,
            muscle_name=muscle_labels[muscle],
            show_ylabel=(row == 2),
            show_xlabel=(row == len(muscle_order) - 1)
        )

        plot_average_emg_signal_dual(
            ax=axes[row, 1],
            profile_pb=profile_pb_after,
            profile_pe=profile_pe_after,
            color_pb="#3E6488",
            color_pe="#C44E52",
            phase_limits=phase_after,
            ylim=ylim,
            muscle_name=None,
            show_ylabel=False,
            show_xlabel=(row == len(muscle_order) - 1)
        )

    handles = [
        plt.Line2D(
            [0], [0],
            color="#3E6488",
            linewidth=1.8,
            linestyle="-",
            label="PB"
        ),
        plt.Line2D(
            [0], [0],
            color="#C44E52",
            linewidth=1.8,
            linestyle="--",
            label="PE"
        )
    ]

    fig.legend(
        handles=handles,
        loc="upper center",
        ncol=2,
        frameon=False,
        fontsize=11,
        bbox_to_anchor=(0.5, 0.99)
    )

    fig.supylabel(
        "EMG (mV)",
        fontsize=12,
        fontweight="bold",
        x=0.07
        )

    plt.subplots_adjust(
        left=0.12,
        right=0.98,
        bottom=0.07,
        top=0.93,
        hspace=0.12,
        wspace=0.15
    )

    if save_path is not None:
        plt.savefig(
            save_path,
            dpi=600,
            bbox_inches="tight"
        )

    return fig

