MUSCLE_CLASS = {

    "Trapecios mV": "trapecio",

    "Deltoides mV": "deltoides",

    "Triceps mV": "triceps",

    "Biceps mV": "biceps",

    "Escapulares mV": "escapulares"

}

def color_svg(
    svg_file,
    muscle_values,
    cmap,
    norm,
    scale=4,
    crop_margin=8
):
    """
    Colorea un SVG y devuelve la imagen lista para imshow().

    Parameters
    ----------
    svg_file : str
        Ruta del SVG.

    muscle_values : dict
        Diccionario con los valores musculares.

    cmap : matplotlib colormap

    norm : matplotlib Normalize

    scale : int, default=3
        Escala de renderizado.

    crop_margin : int, default=8
        Margen alrededor del dibujo después del recorte.

    Returns
    -------
    image : ndarray
        Imagen RGBA.
    """

    tree = ET.parse(svg_file)
    root = tree.getroot()

    ns = {
        "svg": "http://www.w3.org/2000/svg"
    }

    for style in root.findall(".//svg:style", ns):
      if style.text is not None:
        style.text = style.text.replace(
            ".st70{fill:#161515;}",
            ".st70{fill:#E6C89E;}"
        )

    BASE_MUSCLE_COLOR = "#e2e0e0"
    # Puedes probar:
    # "#707070"
    # "#8A8A8A"
    # "#A0A0A0"

    BASE_MUSCLE_COLOR = "#F2D8B3"   # Gris para músculos no instrumentados
    for path in root.findall(".//svg:path", ns):
      cls = path.get("class")
      if cls is None:
        continue

      if cls == "st70":
        path.attrib.pop("style", None)
        path.set("fill", BASE_MUSCLE_COLOR)
        path.set("stroke", "#D8BC92")
        path.set("stroke-width", "0.2")
        continue

      if cls in muscle_values:
        value = muscle_values[cls]

        if np.isnan(value):

            color = BASE_MUSCLE_COLOR

        else:

            color = mpl.colors.to_hex(
                cmap(norm(value))
            )

        path.attrib.pop("style", None)
        path.set("fill", color)
        path.set("style", f"fill:{color};")
        path.set("stroke", "#555555")
        path.set("stroke-width", "0.2")

    svg_bytes = ET.tostring(
        root,
        encoding="utf-8",
        method="xml"
    )

    png_bytes = cairosvg.svg2png(
        bytestring=svg_bytes,
        scale=scale
    )

    image = mpimg.imread(
        io.BytesIO(png_bytes),
        format="png"
    )

    if image.shape[-1] == 4:

        alpha = image[:, :, 3]

        mask = alpha > 0

        if np.any(mask):

            rows = np.where(mask.any(axis=1))[0]
            cols = np.where(mask.any(axis=0))[0]

            r0 = max(rows[0] - crop_margin, 0)
            r1 = min(rows[-1] + crop_margin + 1, image.shape[0])

            c0 = max(cols[0] - crop_margin, 0)
            c1 = min(cols[-1] + crop_margin + 1, image.shape[1])

            image = image[
                r0:r1,
                c0:c1
            ]

    return image

def plot_emg_muscle_glyph(
    df_metrics,
    subject="01",
    metric="RMS",
    cmap="viridis",
    save=False,
    output_dir=None,
    dpi=600
):

    """
    Mapa anatómico de activación muscular utilizando
    un SVG como plantilla.

    Parámetros
    ----------
    df_metrics : DataFrame
        DataFrame con las métricas EMG.

    subject : str

    metric : str
        RMS
        iEMG
        MDF
        relative_activation_%

    cmap : str
        Colormap de matplotlib.

    save : bool

    output_dir : str

    dpi : int
    """
    mpl.rcParams["savefig.dpi"] = dpi

    metric_labels = {

        "RMS": "RMS",

        "iEMG": "iEMG",

        "MDF": "MDF (Hz)",

        "relative_activation_%":
            "Activación relativa (%)"

    }

    df = df_metrics.copy()

    df = df[
        df.subject == subject
    ]

    if df.empty:

        print("No existen datos para este sujeto.")

        return

    conditions = [

        ("PB", "A"),

        ("PB", "D"),

        ("PE", "A"),

        ("PE", "D")

    ]

    panel_titles = {

        ("PB", "A"): "PB · Pre",

        ("PB", "D"): "PB · Post",

        ("PE", "A"): "PE · Pre",

        ("PE", "D"): "PE · Post"

    }

    all_values = df[metric].dropna()

    vmin = np.percentile(
        all_values,
        5
    )

    vmax = np.percentile(
        all_values,
        95
    )

    cmap = plt.get_cmap(cmap)

    norm = mpl.colors.Normalize(

        vmin=vmin,

        vmax=vmax

    )

    from matplotlib.gridspec import GridSpec

    fig = plt.figure(figsize=(13, 8.5))
    gs = GridSpec(
        2,
        3,
        figure=fig,
        width_ratios=[1,1,0.03],
        height_ratios=[1, 1],
        wspace=0.08,
        hspace=0.10

        )

    axes = [
        fig.add_subplot(gs[0, 0]),
        fig.add_subplot(gs[0, 1]),
        fig.add_subplot(gs[1, 0]),
        fig.add_subplot(gs[1, 1])
        ]

    cax = fig.add_subplot(gs[:, 2])

    delta = 0.05  # prueba entre 0.03 y 0.07

    for ax in axes[2:]:
      pos = ax.get_position()
      ax.set_position([
          pos.x0,
          pos.y0 + delta,
          pos.width,
          pos.height
          ])

    for ax, (test_type, phase) in zip(axes, conditions):

        subset = df[
            (df.test_type == test_type) &
            (df.phase == phase)
        ]

        values = (
            subset
            .groupby("muscle")[metric]
            .mean()
            .to_dict()
        )

        svg_values = {}

        for df_name, svg_name in MUSCLE_CLASS.items():

            svg_values[svg_name] = values.get(
                df_name,
                np.nan
            )

        img = color_svg(

            svg_file=SVG_TEMPLATE,

            muscle_values=svg_values,

            cmap=cmap,

            norm=norm

        )

        ax.imshow(
            img
            )

        ax.set_axis_off()

        ax.set_title(

            panel_titles[(test_type, phase)],

            fontsize=12,

            fontweight="bold",

            pad=0,

            color="#303030"

        )

    sm = mpl.cm.ScalarMappable(

        cmap=cmap,

        norm=norm

    )

    sm.set_array([])

    cbar = fig.colorbar(
        sm,
        cax=cax

        )
    from matplotlib.ticker import MaxNLocator
    cbar.locator = MaxNLocator(nbins=5)
    cbar.update_ticks()

    cbar.set_label(

        metric_labels[metric],

        fontsize=10,

        labelpad=12

    )

    cbar.outline.set_visible(False)

    cbar.ax.tick_params(

        labelsize=8,

        colors="#505050"

    )

    fig.suptitle(

        "Mapa Anatómico de Activación Muscular",

        fontsize=12,

        fontweight="semibold",

        y=0.94

    )

    fig.text(

        0.5,

        0.90,

        f"Sujeto {str(subject).zfill(2)}   •   {metric_labels[metric]}",

        ha="center",

        fontsize=11,

        color="#5A5A5A"

    )

    fig.text(
        0.5,
        0.125,
        "PB = Prueba Básica   •   PE = Prueba Extrema\n"
        "Pre = Pre-intervención   •   Post = Post-intervención\n"
        "EMG: Deltoides medio • Tríceps braquial • Trapecio superior",
        ha="center",
        fontsize=8.5,
        color="#707070"
        )

    fig.text(
        0.215,
        0.86,
        "Anterior",
        ha="center",
        va="bottom",
        fontsize=9,
        color="#707070"
    )

    fig.text(
        0.395,
        0.86,
        "Posterior",
        ha="center",
        va="bottom",
        fontsize=9,
        color="#707070"
    )

    fig.text(
        0.595,
        0.86,
        "Anterior",
        ha="center",
        va="bottom",
        fontsize=9,
        color="#707070"
    )

    fig.text(
        0.78,
        0.86,
        "Posterior",
        ha="center",
        va="bottom",
        fontsize=9,
        color="#707070"
      )

    if save:
      if output_dir is None:
        output_dir = os.path.join(
            EMG_RESULTS_PATH,
            "Muscle_Glyphs",
            metric
    )

      os.makedirs(
      output_dir,
      exist_ok=True

      )

      filename = os.path.join(
          output_dir,
          f"Subject_{str(subject).zfill(2)}_{metric}_MuscleGlyph.png"
          )

      plt.savefig(
      filename,
      dpi=dpi,
      bbox_inches="tight",
      facecolor="white"
      )

      print(f"✔ Guardado: {filename}")
      plt.close(fig)
    else:
      plt.show()

