"""# **7.35. Tabla metricas por fase**"""

def build_emg_phase_summary_table_pretty(
    df_metrics,
    round_digits=3,
    export_excel=False,
    excel_name="EMG_Phase_Summary_Table.xlsx"
):
    """
    Genera una tabla resumen de métricas EMG
    agrupadas por fase de movimiento.

    Parámetros
    ----------
    df_metrics : pd.DataFrame
        Salida de extract_emg_metrics_by_phase().

    round_digits : int
        Número de decimales.

    export_excel : bool
        Exportar a Excel.

    excel_name : str
        Nombre del archivo Excel.

    Retorna
    -------
    pd.io.formats.style.Styler
    """

    metrics = [

        "RMS",

        "iEMG",

        "MDF",

        "relative_activation_%"

    ]

    test_translation = {

        "PB": "Básica",

        "PE": "Extrema"

    }

    phase_translation = {

        "A": "Pre-intervención",

        "D": "Post-intervención"

    }

    movement_phase_translation = {

        1: "Fase 1",

        2: "Fase 2",

        3: "Fase 3",

        4: "Fase 4"

    }

    muscle_translation = {

        "Trapecios mV": "Trapecio superior",

        "Escapulares mV": "Escapulares",

        "Triceps mV": "Tríceps braquial",

        "Biceps mV": "Bíceps braquial",

        "Deltoides mV": "Deltoides anterior"

    }

    grouped = df_metrics.groupby(

        [

            "subject",

            "test_type",

            "phase",

            "movement_phase",

            "muscle"

        ]

    )

    summary_rows = []

    for (

        subject,

        test_type,

        phase,

        movement_phase,

        muscle

    ), group in grouped:

        row = {

            "Sujeto":
                subject,

            "Tipo de prueba":
                test_translation.get(
                    test_type,
                    test_type
                ),

            "Momento":
                phase_translation.get(
                    phase,
                    phase
                ),

            "Fase motora":
                movement_phase_translation.get(
                    movement_phase,
                    movement_phase
                ),

            "Músculo":
                muscle_translation.get(
                    muscle,
                    muscle
                )

        }

        for metric in metrics:

            mean_val = np.mean(
                group[metric]
            )

            std_val = np.std(
                group[metric],
                ddof=1
            )

            row[metric] = (

                f"{mean_val:.{round_digits}f}"

                f" ± "

                f"{std_val:.{round_digits}f}"

            )

            row[f"{metric}_raw"] = (
                mean_val
            )

        summary_rows.append(
            row
        )

    summary_table = (

        pd.DataFrame(
            summary_rows
        )

        .sort_values(

            by=[

                "Sujeto",

                "Tipo de prueba",

                "Momento",

                "Fase motora",

                "Músculo"

            ]

        )

        .reset_index(
            drop=True
        )

    )

    raw_cols = [

        f"{metric}_raw"

        for metric in metrics

    ]

    display_table = (

        summary_table

        .drop(
            columns=raw_cols
        )

        .rename(

            columns={

                "RMS":
                    "RMS",

                "iEMG":
                    "iEMG",

                "MDF":
                    "MDF (Hz)",

                "relative_activation_%":
                    "Activación relativa (%)"

            }

        )

    )

    styled = (

        display_table.style

        .background_gradient(
            subset=["RMS"],
            cmap="Greys",
            gmap=summary_table["RMS_raw"],
            low=0.92,
            high=0.02
        )

        .background_gradient(
            subset=["iEMG"],
            cmap="Blues",
            gmap=summary_table["iEMG_raw"],
            low=0.92,
            high=0.02
        )

        .background_gradient(
            subset=["MDF (Hz)"],
            cmap="BuGn",
            gmap=summary_table["MDF_raw"],
            low=0.92,
            high=0.02
        )

        .background_gradient(
            subset=["Activación relativa (%)"],
            cmap="BuPu",
            gmap=summary_table[
                "relative_activation_%_raw"
            ],
            low=0.92,
            high=0.02
        )

        .set_table_styles([

            {

                "selector": "table",

                "props": [

                    ("border-collapse", "separate"),

                    ("border-spacing", "0px"),

                    ("margin", "30px auto"),

                    ("overflow", "hidden"),

                    ("border-radius", "18px"),

                    ("box-shadow",
                     "0 6px 18px rgba(15,23,42,0.06)"),

                    ("background-color",
                     "white"),

                    ("font-family",
                     "Times New Roman")

                ]

            },

            {

                "selector": "th",

                "props": [

                    ("background",
                     "#64748B"),

                    ("color",
                     "white"),

                    ("font-weight",
                     "bold"),

                    ("text-align",
                     "center")

                ]

            }

        ])

        .set_properties(

            subset=[

                "Sujeto",

                "Tipo de prueba",

                "Momento",

                "Fase motora",

                "Músculo"

            ],

            **{

                "font-weight":
                    "bold",

                "background-color":
                    "#F8FAFC",

                "color":
                    "#334155"

            }

        )

        .set_caption(
            "Tabla resumen de métricas EMG por fase de movimiento"
        )

        .hide(axis="index")

    )

    if export_excel:

        (

            summary_table

            .drop(
                columns=raw_cols
            )

            .to_excel(
                excel_name,
                index=False
            )

        )

        print(
            f"✔ Tabla exportada: {excel_name}"
        )

    return styled

