"""# **8. ECG & SPO2 DATA**

# **8.1.  Utilidades de limpieza de datos**
"""

def remove_outliers_iqr(
    df,
    column,
    iqr_factor=1.5
):
    """
    Elimina valores atípicos mediante el método IQR e interpola
    los valores faltantes.

    Parámetros
    ----------
    df : pd.DataFrame
        DataFrame de entrada.
    column : str
        Columna a procesar.
    iqr_factor : float, opcional
        Multiplicador del rango intercuartílico.

    Retorna
    -------
    pd.DataFrame
        DataFrame depurado.
    """

    df = df.copy()

    q1 = df[column].quantile(0.25)
    q3 = df[column].quantile(0.75)

    iqr = q3 - q1

    if iqr == 0:
        return df

    lower = q1 - iqr_factor * iqr
    upper = q3 + iqr_factor * iqr

    df[column] = np.where(
        (df[column] < lower)
        | (df[column] > upper),
        np.nan,
        df[column]
    )

    df[column] = (
        df[column]
        .interpolate(method="linear")
        .bfill()
        .ffill()
    )

    return df

"""# **8.2.  Utilidades temporales**"""

def create_relative_time(
    df,
    timestamp_col="timestamp",
    output_col="time_sec"
):
    """
    Genera un vector de tiempo relativo en segundos.

    Parámetros
    ----------
    df : pd.DataFrame
        DataFrame de entrada.
    timestamp_col : str, opcional
        Nombre de la columna de tiempo.
    output_col : str, opcional
        Nombre de la columna de salida.

    Retorna
    -------
    pd.DataFrame
        DataFrame con el tiempo relativo.
    """

    df = df.copy()

    if timestamp_col not in df.columns:
        raise ValueError(
            f"Columna no encontrada: {timestamp_col}"
        )

    if not pd.api.types.is_datetime64_any_dtype(
        df[timestamp_col]
    ):
        df[timestamp_col] = pd.to_datetime(
            df[timestamp_col]
        )

    df[output_col] = (
        df[timestamp_col]
        - df[timestamp_col].iloc[0]
    ).dt.total_seconds()

    return df

"""# **8.3.  Procesamiento de señales ECG**"""

def process_ecg(
    df,
    lowcut=0.5,
    highcut=40,
    filter_order=4
):
    """
    Procesa señales ECG mediante limpieza, filtrado y suavizado.

    Parámetros
    ----------
    df : pd.DataFrame
        DataFrame ECG original.
    lowcut : float, opcional
        Frecuencia de corte inferior (Hz).
    highcut : float, opcional
        Frecuencia de corte superior (Hz).
    filter_order : int, opcional
        Orden del filtro Butterworth.

    Retorna
    -------
    pd.DataFrame
        DataFrame ECG procesado.
    """

    df = df.copy()

    df["timestamp"] = pd.to_datetime(
        df["Phone timestamp"]
    )

    df = create_relative_time(
        df,
        timestamp_col="timestamp",
        output_col="tiempo"
    )

    ecg = (
        df["ecg [uV]"]
        .astype(float)
        .interpolate()
        .bfill()
        .ffill()
        .values
    )

    dt = np.mean(
        np.diff(df["tiempo"])
    )

    fs = 1 / dt

    ecg = ecg - np.mean(ecg)

    ecg_detrended = detrend(ecg)

    nyquist = 0.5 * fs

    highcut = min(
        highcut,
        0.45 * fs
    )

    low = lowcut / nyquist
    high = highcut / nyquist

    b, a = butter(
        filter_order,
        [low, high],
        btype="band"
    )

    ecg_filtered = filtfilt(
        b,
        a,
        ecg_detrended
    )

    smooth_window = int(fs * 0.03)

    if smooth_window % 2 == 0:
        smooth_window += 1

    smooth_window = max(
        smooth_window,
        5
    )

    ecg_smooth = savgol_filter(
        ecg_filtered,
        window_length=smooth_window,
        polyorder=2
    )

    df["ecg_raw"] = df["ecg [uV]"]
    df["ecg_filtered"] = ecg_filtered
    df["ecg_smooth"] = ecg_smooth

    df.attrs["fs"] = fs

    print(
        f"✔ ECG fs = {fs:.2f} Hz"
    )

    return df

"""# **8.4.  Procesamiento de intervalos RR**"""

def process_rr(df):
    """
    Procesa intervalos RR mediante limpieza, interpolación y suavizado.

    Parámetros
    ----------
    df : pd.DataFrame
        DataFrame RR original.

    Retorna
    -------
    pd.DataFrame
        DataFrame RR procesado.
    """

    df = df.copy()

    df["timestamp"] = pd.to_datetime(
        df["Phone timestamp"],
        errors="coerce"
    )

    df = df.dropna(
        subset=["timestamp"]
    )

    df["RR-interval [ms]"] = pd.to_numeric(
        df["RR-interval [ms]"],
        errors="coerce"
    )

    df = df.sort_values(
        "timestamp"
    )

    df = df.drop_duplicates(
        subset="timestamp"
    )

    dt = (
        df["timestamp"]
        .diff()
        .dt
        .total_seconds()
    )

    df = df[
        (dt > 0)
        | (dt.isna())
    ]

    df = df.reset_index(
        drop=True
    )

    df.loc[
        (
            df["RR-interval [ms]"] < 250
        )
        | (
            df["RR-interval [ms]"] > 2000
        ),
        "RR-interval [ms]"
    ] = np.nan

    df["RR-interval [ms]"] = (
        df["RR-interval [ms]"]
        .interpolate(
            method="linear",
            limit=2
        )
        .bfill()
        .ffill()
    )

    df = create_relative_time(
        df,
        timestamp_col="timestamp",
        output_col="tiempo"
    )

    rr_med = medfilt(
        df["RR-interval [ms]"],
        kernel_size=3
    )

    window = min(
        11,
        len(df)
    )

    if window % 2 == 0:
        window -= 1

    window = max(
        window,
        5
    )

    df["rr_smooth"] = savgol_filter(
        rr_med,
        window_length=window,
        polyorder=2,
        mode="nearest"
    )

    df["rr_raw"] = df["RR-interval [ms]"]

    df.attrs["signal_type"] = "RR"

    print(
        f"✔ RR samples: {len(df)}"
    )

    return df

"""# **8.5.  Procesamiento de frecuencia cardíaca**"""

def process_hr(df):
    """
    Procesa señales de frecuencia cardíaca mediante limpieza,
    interpolación y suavizado.

    Parámetros
    ----------
    df : pd.DataFrame
        DataFrame HR original.

    Retorna
    -------
    pd.DataFrame
        DataFrame HR procesado.
    """

    df = df.copy()

    df["timestamp"] = pd.to_datetime(
        df["Phone timestamp"],
        errors="coerce"
    )

    df = df.dropna(
        subset=["timestamp"]
    )

    df["HR [bpm]"] = pd.to_numeric(
        df["HR [bpm]"],
        errors="coerce"
    )

    df = df.sort_values(
        "timestamp"
    )

    df = df.drop_duplicates(
        subset="timestamp"
    )

    dt = (
        df["timestamp"]
        .diff()
        .dt
        .total_seconds()
    )

    df = df[
        (dt > 0)
        | (dt.isna())
    ]

    df = df.reset_index(
        drop=True
    )

    df.loc[
        (
            df["HR [bpm]"] < 30
        )
        | (
            df["HR [bpm]"] > 220
        ),
        "HR [bpm]"
    ] = np.nan

    df["HR [bpm]"] = (
        df["HR [bpm]"]
        .interpolate(
            method="linear",
            limit=2
        )
        .bfill()
        .ffill()
    )

    df = create_relative_time(
        df,
        timestamp_col="timestamp",
        output_col="tiempo"
    )

    hr_med = medfilt(
        df["HR [bpm]"],
        kernel_size=3
    )

    window = min(
        11,
        len(df)
    )

    if window % 2 == 0:
        window -= 1

    window = max(
        window,
        5
    )

    df["hr_smooth"] = savgol_filter(
        hr_med,
        window_length=window,
        polyorder=2,
        mode="nearest"
    )

    df["hr_raw"] = df["HR [bpm]"]

    df.attrs["signal_type"] = "HR"

    print(
        f"✔ HR samples: {len(df)}"
    )

    return df

"""# **8.6.  Procesamiento de oximetría**"""

def process_oximeter(df):
    """
    Procesa señales de oximetría mediante limpieza,
    interpolación y suavizado.

    Parámetros
    ----------
    df : pd.DataFrame
        DataFrame de oximetría original.

    Retorna
    -------
    pd.DataFrame
        DataFrame procesado.
    """

    df = df.copy()

    if "DATE" in df.columns:
        df = df[
            df["DATE"] != "DATE"
        ]

    df["timestamp"] = pd.to_datetime(
        df["DATE"].astype(str)
        + " "
        + df["TIME"].astype(str),
        format="%d/%m/%Y %H:%M:%S",
        errors="coerce"
    )

    df = df.dropna(
        subset=["timestamp"]
    )

    for col in [
        "SPO2",
        "PULSE",
        "PI"
    ]:
        df[col] = pd.to_numeric(
            df[col],
            errors="coerce"
        )

    df = df.sort_values(
        "timestamp"
    )

    df = df.drop_duplicates(
        subset="timestamp"
    )

    dt = (
        df["timestamp"]
        .diff()
        .dt
        .total_seconds()
    )

    df = df[
        (dt > 0)
        | (dt.isna())
    ]

    df = df.reset_index(
        drop=True
    )

    df = create_relative_time(
        df,
        timestamp_col="timestamp",
        output_col="tiempo"
    )

    df = remove_outliers_iqr(
        df,
        "SPO2"
    )

    df = remove_outliers_iqr(
        df,
        "PULSE"
    )

    df = remove_outliers_iqr(
        df,
        "PI"
    )

    df["SPO2"] = df["SPO2"].clip(
        lower=50,
        upper=100
    )

    df["PULSE"] = df["PULSE"].clip(
        lower=30,
        upper=220
    )

    df["PI"] = df["PI"].clip(
        lower=0,
        upper=500
    )

    df["spo2_smooth"] = (
        df["SPO2"]
        .rolling(
            window=5,
            center=True,
            min_periods=1
        )
        .mean()
    )

    df["pulse_smooth"] = (
        df["PULSE"]
        .rolling(
            window=5,
            center=True,
            min_periods=1
        )
        .mean()
    )

    df["pi_smooth"] = (
        df["PI"]
        .rolling(
            window=7,
            center=True,
            min_periods=1
        )
        .mean()
    )

    df["spo2_raw"] = df["SPO2"]
    df["pulse_raw"] = df["PULSE"]
    df["pi_raw"] = df["PI"]

    df.attrs["signal_type"] = "SPO2"

    print(
        f"✔ Muestras de oximetría: {len(df)}"
    )

    return df

"""# **8.7.  Procesamiento de señales**"""

bio_test_list = []

ecg_files = [
    file
    for file in datos
    if file.endswith("ECG.txt")
]

for ecg_file in sorted(ecg_files):

    match = re.match(
        r"(\d{2})_(\d{2})_(PB|PE)_(A|D)",
        ecg_file
    )

    if match is None:
        print(
            f"⚠ Nombre inválido: {ecg_file}"
        )
        continue

    test_id, subject, test_type, phase = (
        match.groups()
    )

    base_name = (
        f"{test_id}_{subject}_"
        f"{test_type}_{phase}"
    )

    hr_file = f"{base_name}_HR.txt"
    rr_file = f"{base_name}_RR.txt"
    spo2_file = f"{base_name}_SPO2.txt"

    missing = [
        file
        for file in [
            ecg_file,
            hr_file,
            rr_file,
            spo2_file
        ]
        if file not in datos
    ]

    if missing:
        print(
            f"⚠ Archivos faltantes: {missing}"
        )
        continue

    try:

        bio_test_list.append({
            "id": int(test_id),
            "subject": int(subject),
            "test_type": test_type,
            "phase": phase,
            "ecg": process_ecg(
                datos[ecg_file]
            ),
            "hr": process_hr(
                datos[hr_file]
            ),
            "rr": process_rr(
                datos[rr_file]
            ),
            "ox": process_oximeter(
                datos[spo2_file]
            )
        })

    except Exception as e:

        print(
            f"Error procesando "
            f"{base_name}: {e}"
        )

print(
    f"✔ Pruebas biomédicas procesadas: "
    f"{len(bio_test_list)}"
)

"""# **8.8.  Verificación de pruebas**"""

for test in bio_test_list:

    print(
        f"S{test['subject']:02d} "
        f"T{test['id']:02d} "
        f"{test['test_type']} "
        f"{test['phase']}"
    )

    print(
        f"ECG : "
        f"{test['ecg']['tiempo'].iloc[-1]:.2f} s"
    )

    print(
        f"HR  : "
        f"{test['hr']['tiempo'].iloc[-1]:.2f} s"
    )

    print(
        f"RR  : "
        f"{test['rr']['tiempo'].iloc[-1]:.2f} s"
    )

    print(
        f"SPO2: "
        f"{test['ox']['tiempo'].iloc[-1]:.2f} s"
    )

    print("-" * 40)

    break

"""# **8.9.  Utilidades de visualización**"""

def add_biosignal_phase_background(
    ax,
    phase_intervals
):
    """
    Agrega regiones sombreadas correspondientes a las fases
    de una prueba sobre un eje temporal.

    Parámetros
    ----------
    ax : matplotlib.axes.Axes
        Eje donde se dibujarán las fases.
    phase_intervals : dict
        Intervalos temporales de cada fase.

    Retorna
    -------
    None
    """

    phase_colors = {
        1: "#DCEEFF",
        2: "#DDF7E3",
        3: "#FFF3D6",
        4: "#FFE0E0"
    }

    for phase, (start, end) in phase_intervals.items():

        ax.axvspan(
            start,
            end,
            color=phase_colors.get(
                phase,
                "#EEEEEE"
            ),
            alpha=0.6,
            zorder=0,
            ec="none"
        )

        ax.axvline(
            end,
            color="black",
            linestyle=":",
            linewidth=0.5,
            alpha=0.6,
            zorder=1
        )

        ax.text(
            (start + end) / 2,
            0.98,
            f"F{phase}",
            transform=ax.get_xaxis_transform(),
            ha="center",
            va="top",
            fontsize=8,
            color="#555555",
            alpha=0.7
        )

def plot_biosignal_panel(
    ax,
    x,
    y_raw,
    y_smooth,
    title,
    ylabel,
    color,
    fill=True,
    fill_alpha=0.005,
    line_width=1.35,
    robust_limits=True,
    ylim_expand=1.0
):
    """
    Grafica una señal fisiológica.
    """

    signal = np.asarray(y_smooth)

    signal = signal[
        np.isfinite(signal)
    ]

    if len(signal) == 0:

        y_min = -1
        y_max = 1

    elif robust_limits:

        y_min = np.percentile(
            signal,
            1
        )

        y_max = np.percentile(
            signal,
            99
        )

    else:

        y_min = np.min(signal)

        y_max = np.max(signal)

    dynamic_range = max(
        y_max - y_min,
        1
    )

    expanded_range = (
        dynamic_range *
        ylim_expand
    )

    center = (
        y_max + y_min
    ) / 2

    y_min = (
        center -
        expanded_range / 2
    )

    y_max = (
        center +
        expanded_range / 2
    )

    padding = (
        0.15 *
        expanded_range
    )

    ax.set_ylim(
        y_min - padding,
        y_max + padding
    )

    ax.set_facecolor(
        "#FCFCFC"
    )

    if fill:

        ax.fill_between(
            x,
            y_smooth,
            y_min - padding,
            color=color,
            alpha=fill_alpha,
            zorder=1
        )

    if y_raw is not None:

        ax.plot(
            x,
            y_raw,
            color=color,
            linewidth=0.45,
            alpha=0.008,
            zorder=2
        )

    ax.plot(
        x,
        y_smooth,
        color=color,
        linewidth=line_width,
        alpha=0.92,
        solid_capstyle="round",
        solid_joinstyle="round",
        zorder=3
    )

    ax.text(
        0.02,
        1.035,
        "■",
        transform=ax.transAxes,
        fontsize=12,
        color=color,
        va="center"
    )

    ax.text(
        0.065,
        1.03,
        title,
        transform=ax.transAxes,
        fontsize=10,
        fontweight="semibold",
        color="#303030",
        va="center"
    )

    ax.set_ylabel(
        ylabel,
        fontsize=9,
        color="#404040"
    )

    ax.grid(
        which="major",
        color="#D6DCE5",
        linewidth=0.6,
        alpha=0.50
    )

    ax.minorticks_on()

    ax.grid(
        which="minor",
        color="#ECEFF4",
        linewidth=0.4,
        alpha=0.65
    )

    ax.spines["top"].set_visible(False)
    ax.spines["right"].set_visible(False)

    ax.spines["left"].set_color("#D2D2D2")
    ax.spines["bottom"].set_color("#D2D2D2")

    ax.spines["left"].set_linewidth(0.8)
    ax.spines["bottom"].set_linewidth(0.8)

    ax.tick_params(
        axis="both",
        which="major",
        length=3,
        width=0.6,
        color="#707070",
        pad=4
    )

    ax.tick_params(
        axis="both",
        which="minor",
        length=2,
        width=0.4,
        color="#B0B0B0"
    )

    ax.margins(x=0)

