def project_phases_to_duration(
    phase_pct,
    duration
):
    """
    Convierte porcentajes de fase
    a intervalos temporales reales.
    """

    phase_intervals = {}

    for phase, (start_pct, end_pct) in phase_pct.items():

        phase_intervals[int(phase)] = (

            start_pct * duration,

            end_pct * duration

        )

    return phase_intervals

