"""# **8.13. Cálculo de coeficiente de variación**"""

def coefficient_variation(x):

    x = np.asarray(x)

    if len(x) < 2:
        return np.nan

    mean = np.mean(x)

    if mean == 0:
        return np.nan

    return (
        100
        * np.std(x, ddof=1)
        / mean
    )

def calculate_sdnn(rr):

    rr = np.asarray(rr)

    if len(rr) < 2:
        return np.nan

    return np.std(
        rr,
        ddof=1
    )

def calculate_rmssd(rr):

    rr = np.asarray(rr)

    if len(rr) < 2:
        return np.nan

    diff_rr = np.diff(rr)

    if len(diff_rr) == 0:
        return np.nan

    return np.sqrt(
        np.mean(diff_rr ** 2)
    )

def calculate_rms(signal):

    signal = np.asarray(signal)

    if len(signal) == 0:
        return np.nan

    return np.sqrt(
        np.mean(signal ** 2)
    )

def calculate_energy(signal):

    signal = np.asarray(signal)

    if len(signal) == 0:
        return np.nan

    return np.sum(signal ** 2)

"""# **8.14. Extraer segmento por intervalo temporal**"""

def extract_phase_segment(
    df,
    start_time,
    end_time
):

    segment = df[
        (df["tiempo"] >= start_time)
        &
        (df["tiempo"] < end_time)
    ]

    return segment.copy()

"""# **8.15. Calcular métricas ECG**"""

def compute_ecg_metrics(df):

    signal = df["ecg_filtered"].values

    if len(signal) == 0:

        return {

            "ECG_RMS": np.nan,
            "ECG_STD": np.nan,
            "ECG_ENERGY": np.nan
        }

    return {

        "ECG_RMS":
            calculate_rms(signal),

        "ECG_STD":
            np.std(signal, ddof=1)
            if len(signal) > 1
            else np.nan,

        "ECG_ENERGY":
            calculate_energy(signal)
    }

"""# **8.16. Calcular métricas HR**"""

def compute_hr_metrics(df):

    signal = df["hr_raw"].values

    if len(signal) == 0:

        return {

            "HR_mean": np.nan,
            "HR_std": np.nan,
            "HR_min": np.nan,
            "HR_max": np.nan,
            "HR_cv": np.nan
        }

    return {

        "HR_mean":
            np.mean(signal),

        "HR_std":
            np.std(signal, ddof=1)
            if len(signal) > 1
            else np.nan,

        "HR_min":
            np.min(signal),

        "HR_max":
            np.max(signal),

        "HR_cv":
            coefficient_variation(signal)
    }

"""# **8.17. Calcular métricas RR**"""

def compute_rr_metrics(df):

    signal = df["rr_raw"].values

    if len(signal) == 0:

        return {

            "RR_mean": np.nan,
            "RR_std": np.nan,
            "RR_min": np.nan,
            "RR_max": np.nan,
            "RR_cv": np.nan,
            "SDNN": np.nan,
            "RMSSD": np.nan
        }

    return {

        "RR_mean":
            np.mean(signal),

        "RR_std":
            np.std(signal, ddof=1)
            if len(signal) > 1
            else np.nan,

        "RR_min":
            np.min(signal),

        "RR_max":
            np.max(signal),

        "RR_cv":
            coefficient_variation(signal),

        "SDNN":
            calculate_sdnn(signal),

        "RMSSD":
            calculate_rmssd(signal)
    }

"""# **8.18. Calcular métricas SPO2**"""

def compute_spo2_metrics(df):

    signal = df["spo2_raw"].values

    if len(signal) == 0:

        return {

            "SpO2_mean": np.nan,
            "SpO2_std": np.nan,
            "SpO2_min": np.nan,
            "SpO2_max": np.nan
        }

    return {

        "SpO2_mean":
            np.mean(signal),

        "SpO2_std":
            np.std(signal, ddof=1)
            if len(signal) > 1
            else np.nan,

        "SpO2_min":
            np.min(signal),

        "SpO2_max":
            np.max(signal)
    }

"""# **8.19. Calcular métricas PI**"""

def compute_pi_metrics(df):

    signal = df["pi_raw"].values

    if len(signal) == 0:

        return {

            "PI_mean": np.nan,
            "PI_std": np.nan,
            "PI_min": np.nan,
            "PI_max": np.nan,
            "PI_cv": np.nan
        }

    return {

        "PI_mean":
            np.mean(signal),

        "PI_std":
            np.std(signal, ddof=1)
            if len(signal) > 1
            else np.nan,

        "PI_min":
            np.min(signal),

        "PI_max":
            np.max(signal),

        "PI_cv":
            coefficient_variation(signal)
    }

"""# **8.20. Construir métricas fisiológicas por fase**"""

def build_bio_metrics_df(
    bio_test_list,
    phase_percentages_dict
):

    metrics_rows = []

    for test in bio_test_list:

        key = (

            str(test["subject"]).zfill(2),

            str(test["id"]).zfill(2),

            test["test_type"],

            test["phase"]

        )

        if key not in phase_percentages_dict:
            continue

        phase_pct = phase_percentages_dict[key]

        ecg_phases = project_phases_to_duration(
            phase_pct,
            test["ecg"]["tiempo"].iloc[-1]
        )

        hr_phases = project_phases_to_duration(
            phase_pct,
            test["hr"]["tiempo"].iloc[-1]
        )

        rr_phases = project_phases_to_duration(
            phase_pct,
            test["rr"]["tiempo"].iloc[-1]
        )

        ox_phases = project_phases_to_duration(
            phase_pct,
            test["ox"]["tiempo"].iloc[-1]
        )

        for phase_id in [1, 2, 3, 4]:

            ecg_seg = extract_phase_segment(
                test["ecg"],
                *ecg_phases[phase_id]
            )

            hr_seg = extract_phase_segment(
                test["hr"],
                *hr_phases[phase_id]
            )

            rr_seg = extract_phase_segment(
                test["rr"],
                *rr_phases[phase_id]
            )

            ox_seg = extract_phase_segment(
                test["ox"],
                *ox_phases[phase_id]
            )

            row = {

                "subject":
                    test["subject"],

                "id":
                    test["id"],

                "test_type":
                    test["test_type"],

                "phase":
                    test["phase"],

                "movement_phase":
                    f"F{phase_id}"
            }

            row.update(
                compute_ecg_metrics(
                    ecg_seg
                )
            )

            row.update(
                compute_hr_metrics(
                    hr_seg
                )
            )

            row.update(
                compute_rr_metrics(
                    rr_seg
                )
            )

            row.update(
                compute_spo2_metrics(
                    ox_seg
                )
            )

            row.update(
                compute_pi_metrics(
                    ox_seg
                )
            )

            metrics_rows.append(row)

    return pd.DataFrame(metrics_rows)

bio_metrics_df = build_bio_metrics_df(
    bio_test_list,
    phase_percentages_dict
)

"""# **8.21. Graficar mapa fisiológico expandido**"""

def plot_bio_phase_heatmap(
    bio_metrics_df,
    subject="01",
    save_path=None
):
    """
    Genera un heatmap fisiológico completo
    conservando todas las fases del movimiento.

    Parámetros
    ----------
    bio_metrics_df : pd.DataFrame
        DataFrame de métricas fisiológicas.
    subject : str, opcional
        Identificador del sujeto.
    save_path : str, opcional
        Directorio de exportación.

    Retorna
    -------
    None
    """

    df = bio_metrics_df.copy()

    df = df[
        df["subject"].astype(str).str.zfill(2)
        ==
        str(subject).zfill(2)
    ]

    if len(df) == 0:

        print(
            f"No hay datos para sujeto {subject}"
        )

        return

    metrics = [
        "HR_mean",
        "RR_mean",
        "SDNN",
        "RMSSD",
        "SpO2_mean",
        "PI_mean"
    ]

    metric_labels = {
        "HR_mean": "HR",
        "RR_mean": "RR",
        "SDNN": "SDNN",
        "RMSSD": "RMSSD",
        "SpO2_mean": "SpO₂",
        "PI_mean": "PI"
    }

    phase_order = [
        "F1",
        "F2",
        "F3",
        "F4"
    ]

    condition_order = [
        ("PB", "A"),
        ("PB", "D"),
        ("PE", "A"),
        ("PE", "D")
    ]

    matrix = pd.DataFrame()

    column_names = []

    for test_type, phase in condition_order:

        condition_df = df[
            (df["test_type"] == test_type)
            &
            (df["phase"] == phase)
        ]

        for mov_phase in phase_order:

            col_name = (
                f"{test_type}-{phase}\n{mov_phase}"
            )

            column_names.append(
                col_name
            )

            values = []

            for metric in metrics:

                subset = condition_df[
                    condition_df[
                        "movement_phase"
                    ] == mov_phase
                ]

                values.append(
                    subset[metric].mean()
                )

            matrix[col_name] = values

    matrix.index = [
        metric_labels[m]
        for m in metrics
    ]

    matrix_raw = matrix.copy()

    matrix_norm = matrix.copy()

    for idx in matrix_norm.index:

        row = matrix_norm.loc[idx]

        min_val = row.min()
        max_val = row.max()

        if max_val > min_val:

            matrix_norm.loc[idx] = (
                (row - min_val)
                /
                (max_val - min_val)
            )

        else:

            matrix_norm.loc[idx] = 0.5

    plt.figure(
        figsize=(14, 5.5)
    )

    sns.heatmap(
        matrix_norm,
        annot=matrix_raw.round(1),
        fmt="",
        cmap="RdYlBu_r",
        linewidths=0.8,
        linecolor="white",
        cbar_kws={
            "label":
            "Valor relativo normalizado"
        }
    )

    plt.title(
        f"Perfil Fisiológico por Fase · "
        f"Sujeto {str(subject).zfill(2)}",
        fontsize=16,
        fontweight="semibold",
        pad=18
    )

    plt.xlabel("")
    plt.ylabel("")

    plt.tight_layout()

    if save_path is not None:

        os.makedirs(
            save_path,
            exist_ok=True
        )

        filename = os.path.join(
            save_path,
            f"{str(subject).zfill(2)}_"
            f"BIO_PHASE_HEATMAP.png"
        )

        plt.savefig(
            filename,
            dpi=600,
            bbox_inches="tight",
            facecolor="white",
            edgecolor="none",
            format="png"
        )

        print(
            f"✔ Guardado: {filename}"
        )

        plt.close()

    else:

        plt.show()

"""# **8.22. Resultados Graficar mapa fisiológico expandido**"""

plot_bio_phase_heatmap(
    bio_metrics_df,
    subject="01"
)

"""# **8.23. Graficar radares fisiológicos por tipo de prueba**"""

def plot_bio_radar_by_test(
    bio_metrics_df,
    subject="01",
    test_type="PB",
    save_path=None,
    dpi=600
):

    sns.set_theme(
        style="white",
        context="paper"
    )

    plt.rcParams.update({
        "font.family": "serif",
        "font.serif": [
            "Times New Roman",
            "STIXGeneral"
        ],
        "font.size": 11,
        "axes.titlesize": 14,
        "axes.titleweight": "normal"
    })

    metrics = [
        "HR_mean",
        "RR_mean",
        "SDNN",
        "RMSSD",
        "SpO2_mean",
        "PI_mean"
    ]

    metric_titles = {
        "HR_mean": "HR",
        "RR_mean": "RR",
        "SDNN": "SDNN",
        "RMSSD": "RMSSD",
        "SpO2_mean": "SpO₂",
        "PI_mean": "PI"
    }

    phase_order = [
        "F1",
        "F2",
        "F3",
        "F4"
    ]

    colors = {
        "A": "#4C5C92",   # Azul científico
        "D": "#2A9D8F"    # Verde petróleo
    }

    df = bio_metrics_df.copy()

    df = df[
        (
            df["subject"]
            .astype(str)
            .str.zfill(2)
        )
        ==
        str(subject).zfill(2)
    ]

    df = df[
        df["test_type"]
        ==
        test_type
    ]

    if len(df) == 0:

        print(
            "No hay datos disponibles."
        )

        return

    angles = np.linspace(
        0,
        2 * np.pi,
        len(phase_order),
        endpoint=False
    ).tolist()

    angles += angles[:1]

    fig, axes = plt.subplots(
        2,
        3,
        figsize=(16, 10),
        subplot_kw={"polar": True}
    )

    axes = axes.flatten()

    for idx, metric in enumerate(metrics):

        ax = axes[idx]

        stats = {
            "A": [],
            "D": []
        }

        for phase in ["A", "D"]:

            phase_values = []

            for mov_phase in phase_order:

                subset = df[
                    (df["phase"] == phase)
                    &
                    (
                        df["movement_phase"]
                        == mov_phase
                    )
                ][metric]

                phase_values.append(
                    subset.mean()
                )

            stats[phase] = phase_values

        # Escala radial real

        all_values = []

        for phase in ["A", "D"]:

            all_values.extend(
                [
                    v
                    for v in stats[phase]
                    if not np.isnan(v)
                ]
            )

        if len(all_values) > 0:

            rmin = np.min(all_values)
            rmax = np.max(all_values)

            if rmax > rmin:

                margin = (
                    rmax - rmin
                ) * 0.10

                ax.set_ylim(
                    rmin - margin,
                    rmax + margin
                )

        stats["A"] += stats["A"][:1]
        stats["D"] += stats["D"][:1]

        for phase in ["A", "D"]:

            linestyle = "-"
            marker = "o"

            if phase == "D":

                linestyle = "--"
                marker = "s"

            mean_values = np.array(
                stats[phase]
            )

            ax.fill(
                angles,
                mean_values,
                color=colors[phase],
                alpha=0.03,
                zorder=1
            )

            ax.plot(
                angles,
                mean_values,
                color=colors[phase],
                linewidth=3.5,
                linestyle=linestyle,
                marker=marker,
                markersize=6,
                markeredgecolor="white",
                markeredgewidth=0.8,
                zorder=3
            )

        ax.set_xticks(
            angles[:-1]
        )

        ax.set_xticklabels(
            phase_order,
            fontsize=11
        )

        ax.tick_params(
            axis="y",
            labelsize=8,
            colors="#707070"
        )

        ax.set_rlabel_position(
            22
        )

        ax.grid(
            True,
            linestyle="--",
            linewidth=0.8,
            alpha=0.25
        )

        ax.xaxis.grid(
            True,
            linestyle="-",
            linewidth=0.7,
            alpha=0.25
        )

        ax.set_title(
            f"{chr(65 + idx)}. "
            f"{metric_titles[metric]}",
            pad=24
        )

        ax.spines["polar"].set_color(
            "#444"
        )

