"""# **8.34.  Calcular perfil fisiológico promedio**"""

def compute_average_bio_profile(
    tests,
    source_key,
    signal_name,
    n_points=101
):
    """
    Calcula el perfil promedio normalizado
    de una señal fisiológica.

    Parámetros
    ----------
    tests : list
        Lista de pruebas fisiológicas filtradas.

    source_key : str
        Tipo de señal dentro del diccionario:
        ecg, hr, rr u ox.

    signal_name : str
        Nombre de la señal procesada.

    n_points : int
        Número de puntos para normalización temporal.

    Retorna
    -------
    dict
        Perfil promedio:
        x, mean, std, n_trials
    """

    profiles = []

    x_target = np.linspace(
        0,
        100,
        n_points
    )

    for test in tests:

        df = test[source_key]

        if signal_name not in df.columns:

            continue

        signal = (
            df[signal_name]
            .astype(float)
            .values
        )

        mask = np.isfinite(
            signal
        )

        signal = signal[
            mask
        ]

        if len(signal) < 5:

            continue

        x_original = np.linspace(
            0,
            100,
            len(signal)
        )

        signal_norm = np.interp(
            x_target,
            x_original,
            signal
        )

        profiles.append(
            signal_norm
        )

    if len(profiles) == 0:

        raise ValueError(
            f"No hay señales válidas para {signal_name}"
        )

    profiles = np.vstack(
        profiles
    )

    return {

        "x": x_target,

        "mean": np.mean(
            profiles,
            axis=0
        ),

        "std": np.std(
            profiles,
            axis=0
        ),

        "n_trials": len(
            profiles
        )
    }

"""# **8.35.  Calcular límites promedio de fase fisiológica**"""

def compute_average_bio_phase_boundaries(
    tests,
    phase_percentages_dict
):
    """
    Calcula los límites promedio de fase
    para perfiles fisiológicos normalizados.

    Parámetros
    ----------
    tests : list
        Lista de pruebas fisiológicas.

    phase_percentages_dict : dict
        Diccionario con porcentajes de fase
        provenientes de cinemática.

    Retorna
    -------
    dict
        Límites promedio:
        F1-F2, F2-F3, F3-F4
        en porcentaje del movimiento.
    """

    phase_values = {
        1: [],
        2: [],
        3: []
    }

    for test in tests:

        key = (
            str(test["subject"]).zfill(2),
            str(test["id"]).zfill(2),
            test["test_type"],
            test["phase"]
        )

        if key not in phase_percentages_dict:

            continue

        phase_pct = (
            phase_percentages_dict[key]
        )

        for phase in [
            1,
            2,
            3
        ]:

            if phase in phase_pct:

                _, end_pct = (
                    phase_pct[phase]
                )

                phase_values[phase].append(
                    end_pct * 100
                )

    phase_limits = {}

    for phase, values in phase_values.items():

        if len(values) > 0:

            phase_limits[phase] = np.mean(
                values
            )

    return phase_limits

"""# **8.36.  Graficar perfil fisiológico promedio**"""

def plot_average_biosignal(
    ax,
    x,
    mean_signal,
    std_signal,
    title,
    ylabel,
    color,
    phase_limits=None,
    fill_alpha=0.18,
    line_width=2.2,
    robust_limits=True,
    ylim_expand=1.0
):
    """
    Grafica una señal fisiológica promedio
    con banda de desviación estándar.

    Parámetros
    ----------
    ax : matplotlib.axes.Axes
        Eje destino.

    x : array
        Vector normalizado 0-100%.

    mean_signal : array
        Señal promedio.

    std_signal : array
        Desviación estándar.

    title : str
        Nombre del panel.

    ylabel : str
        Unidad fisiológica.

    color : str
        Color de la señal.

    phase_limits : dict
        Límites promedio de fases.

    Retorna
    -------
    None
    """

    if phase_limits is not None:

        add_average_phase_background(
            ax,
            phase_limits
        )

    upper = (
        mean_signal
        +
        std_signal
    )

    lower = (
        mean_signal
        -
        std_signal
    )

    if robust_limits:

        y_min = np.percentile(
            lower,
            1
        )

        y_max = np.percentile(
            upper,
            99
        )

    else:

        y_min = np.min(
            lower
        )

        y_max = np.max(
            upper
        )

    dynamic_range = max(
        y_max - y_min,
        1
    )

    expanded_range = (
        dynamic_range
        *
        ylim_expand
    )

    center = (
        y_max
        +
        y_min
    ) / 2


    y_min = (
        center
        -
        expanded_range / 2
    )

    y_max = (
        center
        +
        expanded_range / 2
    )

    padding = (
        0.12
        *
        expanded_range
    )

    ax.set_ylim(
        y_min - padding,
        y_max + padding
    )

    ax.fill_between(
        x,
        lower,
        upper,
        color=color,
        alpha=fill_alpha,
        linewidth=0,
        zorder=2
    )

    ax.plot(
        x,
        mean_signal,
        color=color,
        linewidth=line_width,
        alpha=0.95,
        solid_capstyle="round",
        solid_joinstyle="round",
        zorder=3
    )

    ax.text(
        0.02,
        1.035,
        "■",
        transform=ax.transAxes,
        fontsize=12,
        color=color,
        va="center"
    )

    ax.text(
        0.065,
        1.03,
        title,
        transform=ax.transAxes,
        fontsize=10,
        fontweight="semibold",
        color="#303030",
        va="center"
    )

    ax.set_ylabel(
        ylabel,
        fontsize=9,
        color="#404040"
    )

    ax.grid(
        which="major",
        color="#D6DCE5",
        linewidth=0.6,
        alpha=0.50
    )

    ax.minorticks_on()

    ax.grid(
        which="minor",
        color="#ECEFF4",
        linewidth=0.4,
        alpha=0.65
    )

    ax.spines["top"].set_visible(False)
    ax.spines["right"].set_visible(False)

    ax.spines["left"].set_color(
        "#D2D2D2"
    )

    ax.spines["bottom"].set_color(
        "#D2D2D2"
    )

    ax.tick_params(
        axis="both",
        which="major",
        length=3,
        width=0.6,
        color="#707070"
    )

    ax.tick_params(
        axis="both",
        which="minor",
        length=2,
        width=0.4,
        color="#B0B0B0"
    )

    ax.yaxis.set_major_locator(
        MaxNLocator(5)
    )

    ax.margins(
        x=0
    )

    ax.set_xlabel(
        "% del movimiento",
        fontsize=9,
        color="#404040"
    )

"""# **8.37.  Graficar análisis fisiológico promedio**"""

def plot_average_biosignal_analysis(
    bio_test_list,
    phase_percentages_dict,
    subject,
    test_type,
    phase,
    save_path=None
):
    """
    Genera el perfil fisiológico promedio
    para una condición experimental.

    Señales:
    - Frecuencia cardíaca
    - Intervalo RR
    - SpO2
    - Índice de perfusión
    """
    tests = [

        test

        for test in bio_test_list

        if (
            test["subject"] == int(subject)
            and
            test["test_type"] == test_type
            and
            test["phase"] == phase
        )
    ]

    if len(tests) == 0:

        raise ValueError(
            "No se encontraron pruebas."
        )

    phase_limits = (
        compute_average_bio_phase_boundaries(
            tests,
            phase_percentages_dict
        )
    )

    hr = compute_average_bio_profile(
        tests,
        "hr",
        "hr_smooth"
    )

    rr = compute_average_bio_profile(
        tests,
        "rr",
        "rr_smooth"
    )

    spo2 = compute_average_bio_profile(
        tests,
        "ox",
        "spo2_smooth"
    )

    pi = compute_average_bio_profile(
        tests,
        "ox",
        "pi_smooth"
    )

    colors = (

        "#4C78A8",  # HR
        "#5B8FA8",  # RR
        "#2A9DBB",  # SpO2
        "#C23B3B"   # PI

    )

    fig, axs = plt.subplots(
        2,
        2,
        figsize=(14, 8)
    )

    axs = axs.flatten()

    plot_average_biosignal(
        axs[0],
        hr["x"],
        hr["mean"],
        hr["std"],
        "Frecuencia cardíaca",
        "bpm",
        colors[0],
        phase_limits,
        ylim_expand=2.5
    )

    plot_average_biosignal(
        axs[1],
        rr["x"],
        rr["mean"],
        rr["std"],
        "Intervalo RR",
        "ms",
        colors[1],
        phase_limits,
        ylim_expand=2.5
    )

    plot_average_biosignal(
        axs[2],
        spo2["x"],
        spo2["mean"],
        spo2["std"],
        "SpO₂ (%)",
        "%",
        colors[2],
        phase_limits,
        ylim_expand=3.5
    )

    plot_average_biosignal(
        axs[3],
        pi["x"],
        pi["mean"],
        pi["std"],
        "Índice de perfusión (PI)",
        "PI",
        colors[3],
        phase_limits,
        ylim_expand=3
    )

    fig.suptitle(
        f"Perfil Fisiológico Promedio · "
        f"Sujeto {int(subject):02d} · "
        f"{test_type} · "
        f"{phase}",
        fontsize=12,
        fontweight="semibold",
        y=0.98
    )

    fig.text(
        0.5,
        0.93,
        f"Promedio de {len(tests)} ensayos normalizados · "
        "Línea: media · Banda: media ±1 DE",
        ha="center",
        fontsize=9,
        color="#707070"
    )

    phase_legend = [

        Patch(
            facecolor="#DCEEFF",
            edgecolor="none",
            alpha=0.6,
            label="Fase 1"
        ),

        Patch(
            facecolor="#DDF7E3",
            edgecolor="none",
            alpha=0.6,
            label="Fase 2"
        ),

        Patch(
            facecolor="#FFF3D6",
            edgecolor="none",
            alpha=0.6,
            label="Fase 3"
        ),

        Patch(
            facecolor="#FFE0E0",
            edgecolor="none",
            alpha=0.6,
            label="Fase 4"
        )
    ]

    fig.legend(
        handles=phase_legend,
        loc="upper center",
        bbox_to_anchor=(0.5, 0.915),
        ncol=4,
        frameon=False,
        fontsize=9
    )

    plt.subplots_adjust(
        left=0.065,
        right=0.985,
        bottom=0.075,
        top=0.86,
        hspace=0.42,
        wspace=0.22
    )

    if save_path is not None:

        os.makedirs(
            save_path,
            exist_ok=True
        )

        filename = os.path.join(

            save_path,

            f"S{int(subject):02d}_"
            f"{test_type}_"
            f"{phase}_"
            f"BIOSIGNAL_AVERAGE.png"
        )

        plt.savefig(
            filename,
            dpi=600,
            bbox_inches="tight",
            facecolor="white",
            edgecolor="none"
        )

        print(
            f"✔ Guardado: {filename}"
        )

        plt.close(fig)

    else:

        plt.show()

