def plot_average_biosignal_before_after(
    ax,
    profile_before,
    profile_after,
    variable_name,
    units,
    color_before="#3B6FB6",
    color_after="#D1495B",
    phase_limits=None,
    ylim=None,
    show_variable=False,
    show_xlabel=False
):
    """
    Grafica un perfil fisiológico promedio comparando
    Antes vs Después.

    Parámetros
    ----------
    ax : matplotlib.axes.Axes

    profile_before : dict
        Salida de compute_average_bio_profile()

    profile_after : dict
        Salida de compute_average_bio_profile()

    variable_name : str
        Nombre de la variable fisiológica.

    units : str
        Unidad de la variable.

    phase_limits : dict

    ylim : tuple

    show_variable : bool
        Si True muestra el nombre de la variable en el
        lado izquierdo (solo primera columna).

    show_xlabel : bool
    """

    if phase_limits is not None:

        add_average_phase_background(
            ax,
            phase_limits
        )

    ax.fill_between(
        profile_before["x"],
        profile_before["mean"] - profile_before["std"],
        profile_before["mean"] + profile_before["std"],
        color=color_before,
        alpha=0.10
    )

    ax.plot(
        profile_before["x"],
        profile_before["mean"],
        color=color_before,
        linewidth=1.8,
        linestyle="-",
        label="Antes"
    )

    ax.fill_between(
        profile_after["x"],
        profile_after["mean"] - profile_after["std"],
        profile_after["mean"] + profile_after["std"],
        color=color_after,
        alpha=0.10
    )

    ax.plot(
        profile_after["x"],
        profile_after["mean"],
        color=color_after,
        linewidth=1.8,
        linestyle="--",
        label="Después"
    )

    ax.set_xlim(
        profile_before["x"][0],
        profile_before["x"][-1]
    )

    if ylim is not None:

        ax.set_ylim(ylim)

    if show_variable:

        ax.text(
            -0.22,
            0.5,
            variable_name,
            transform=ax.transAxes,
            rotation=90,
            fontsize=10,
            fontweight="bold",
            ha="center",
            va="center",
        )

        ax.text(
            -0.12,
            0.5,
            units,
            transform=ax.transAxes,
            rotation=90,
            fontsize=8,
            color="dimgray",
            ha="center",
            va="center"
        )

    if show_xlabel:

        ax.set_xlabel(
            "% del movimiento",
            fontsize=10
        )

    else:

        ax.tick_params(
            axis="x",
            labelbottom=False
        )


    axis_color = "#C8CDD3"   # Gris suave

    ax.grid(
        True,
        alpha=0.10
        )

    # Spines
    ax.spines["top"].set_visible(False)
    ax.spines["right"].set_visible(False)
    ax.spines["left"].set_color(axis_color)
    ax.spines["bottom"].set_color(axis_color)
    ax.spines["left"].set_linewidth(0.8)
    ax.spines["bottom"].set_linewidth(0.8)

    # Ticks
    ax.tick_params(
        axis="both",
        direction="out",
        length=3,
        width=0.8,
        color=axis_color,      # color de las rayitas
        labelcolor="0.25",     # color de los números
        labelsize=9
        )

def plot_average_bio_subject_comparison(
    bio_test_list,
    phase_percentages_dict,
    subject,
    save_path=None
):
    """
    Genera una figura 4x2 comparando:

                PB                 PE
           Antes  Después     Antes  Después

    Variables:

    - Frecuencia cardíaca
    - Intervalo RR
    - SpO₂
    - Índice de perfusión
    """

    pb_before = [

        t

        for t in bio_test_list

        if (
            t["subject"] == int(subject)
            and
            t["test_type"] == "PB"
            and
            t["phase"] == "A"
        )
    ]

    pb_after = [

        t

        for t in bio_test_list

        if (
            t["subject"] == int(subject)
            and
            t["test_type"] == "PB"
            and
            t["phase"] == "D"
        )
    ]

    pe_before = [

        t

        for t in bio_test_list

        if (
            t["subject"] == int(subject)
            and
            t["test_type"] == "PE"
            and
            t["phase"] == "A"
        )
    ]

    pe_after = [

        t

        for t in bio_test_list

        if (
            t["subject"] == int(subject)
            and
            t["test_type"] == "PE"
            and
            t["phase"] == "D"
        )
    ]

    if (
        len(pb_before) == 0
        or
        len(pb_after) == 0
        or
        len(pe_before) == 0
        or
        len(pe_after) == 0
    ):

        raise ValueError(
            f"No existen todas las condiciones para el sujeto {subject}"
        )

    phase_limits_pb = compute_average_bio_phase_boundaries(
        pb_before + pb_after,
        phase_percentages_dict
    )

    phase_limits_pe = compute_average_bio_phase_boundaries(
        pe_before + pe_after,
        phase_percentages_dict
    )

    variables = [

        (
            "Frecuencia\ncardíaca",
            "bpm",
            "hr",
            "hr_smooth"
        ),

        (
            "Intervalo\nRR",
            "ms",
            "rr",
            "rr_smooth"
        ),

        (
            "SpO₂",
            "%",
            "ox",
            "spo2_smooth"
        ),

        (
            "Índice de\nperfusión",
            "PI",
            "ox",
            "pi_smooth"
        )

    ]

    fig, axs = plt.subplots(
        4,
        2,
        figsize=(10, 10.5),
        sharex=True
    )

    before_color = "#3B6FB6"
    after_color = "#D1495B"

    axs[0, 0].set_title(
        "PB",
        fontsize=12,
        fontweight="bold",
        pad=12
    )

    axs[0, 1].set_title(
        "PE",
        fontsize=12,
        fontweight="bold",
        pad=12
    )

    for row, (

        variable_name,
        units,
        source_key,
        signal_name

    ) in enumerate(variables):

        pb_before_profile = compute_average_bio_profile(
            pb_before,
            source_key,
            signal_name
        )

        pb_after_profile = compute_average_bio_profile(
            pb_after,
            source_key,
            signal_name
        )

        pe_before_profile = compute_average_bio_profile(
            pe_before,
            source_key,
            signal_name
        )

        pe_after_profile = compute_average_bio_profile(
            pe_after,
            source_key,
            signal_name
        )

        ymin = min(

            np.min(pb_before_profile["mean"] - pb_before_profile["std"]),
            np.min(pb_after_profile["mean"] - pb_after_profile["std"]),
            np.min(pe_before_profile["mean"] - pe_before_profile["std"]),
            np.min(pe_after_profile["mean"] - pe_after_profile["std"])

        )

        ymax = max(

            np.max(pb_before_profile["mean"] + pb_before_profile["std"]),
            np.max(pb_after_profile["mean"] + pb_after_profile["std"]),
            np.max(pe_before_profile["mean"] + pe_before_profile["std"]),
            np.max(pe_after_profile["mean"] + pe_after_profile["std"])

        )

        padding = 0.10 * (ymax - ymin)

        ylim = (

            ymin - padding,
            ymax + padding

        )

        plot_average_biosignal_before_after(

            ax=axs[row, 0],

            profile_before=pb_before_profile,
            profile_after=pb_after_profile,

            variable_name=variable_name,
            units=units,

            color_before=before_color,
            color_after=after_color,

            phase_limits=phase_limits_pb,

            ylim=ylim,

            show_variable=True,

            show_xlabel=(row == 3)

        )

        plot_average_biosignal_before_after(

            ax=axs[row, 1],

            profile_before=pe_before_profile,
            profile_after=pe_after_profile,

            variable_name=variable_name,
            units=units,

            color_before=before_color,
            color_after=after_color,

            phase_limits=phase_limits_pe,

            ylim=ylim,

            show_variable=False,

            show_xlabel=(row == 3)

        )

    legend_handles = [

        Line2D(
            [0],
            [0],
            color=before_color,
            lw=2,
            linestyle="-",
            label="Antes"
        ),

        Line2D(
            [0],
            [0],
            color=after_color,
            lw=2,
            linestyle="--",
            label="Después"
        ),

    ]

    fig.legend(

        handles=legend_handles,

        loc="upper center",

        bbox_to_anchor=(0.5, 0.94),

        ncol=6,

        frameon=False,

        fontsize=9

    )

    plt.subplots_adjust(

        left=0.14,

        right=0.98,

        bottom=0.08,

        top=0.88,

        hspace=0.30,

        wspace=0.18

    )

    if save_path is not None:

        os.makedirs(
            save_path,
            exist_ok=True
        )

        filename = os.path.join(

            save_path,

            f"S{int(subject):02d}_BIO_COMPARISON.png"

        )

        plt.savefig(

            filename,

            dpi=600,

            bbox_inches="tight",

            facecolor="white"

        )

        print(f"✔ Figura guardada: {filename}")

        plt.close(fig)

    else:

        plt.show()

subjects = ["01", "02", "03"]

for subject in subjects:

    plot_average_bio_subject_comparison(
        bio_test_list=bio_test_list,
        phase_percentages_dict=phase_percentages_dict,
        subject=subject,
        save_path=None
    )

for subject in sorted({t["subject"] for t in bio_test_list}):

    plot_average_bio_subject_comparison(
        bio_test_list=bio_test_list,
        phase_percentages_dict=phase_percentages_dict,
        subject=subject,
        save_path=ECG_RESULTS_PATH
    )